{"path":"/workspace/backend/internal/services/events_service.go","file_text":"package services

import (
	"database/sql"
	"encoding/json"
	"sync"
	"time"

	"labsystem/internal/models"
)

type EventHub struct {
	mu          sync.RWMutex
	subscribers map[chan models.RealtimeEvent]struct{}
}

var Hub = &EventHub{
	subscribers: make(map[chan models.RealtimeEvent]struct{}),
}

func (h *EventHub) Subscribe() chan models.RealtimeEvent {
	h.mu.Lock()
	defer h.mu.Unlock()
	ch := make(chan models.RealtimeEvent, 100)
	h.subscribers[ch] = struct{}{}
	return ch
}

func (h *EventHub) Unsubscribe(ch chan models.RealtimeEvent) {
	h.mu.Lock()
	defer h.mu.Unlock()
	delete(h.subscribers, ch)
	close(ch)
}

func (h *EventHub) Broadcast(event models.RealtimeEvent) {
	h.mu.RLock()
	defer h.mu.RUnlock()
	for ch := range h.subscribers {
		select {
		case ch <- event:
		default:
		}
	}
}

func BroadcastEvent(db *sql.DB, eventType, entityType, entityId string, payload map[string]interface{}) {
	if payload == nil {
		payload = make(map[string]interface{})
	}
	payloadJSON, _ := json.Marshal(payload)

	var id int64
	var createdAt time.Time
	err := db.QueryRow(`
        INSERT INTO realtime_events (type, entity_type, entity_id, payload, created_at)
        VALUES ($1, $2, $3, $4, NOW())
        RETURNING id, created_at
    `, eventType, entityType, entityId, string(payloadJSON)).Scan(&id, &createdAt)

	if err == nil {
		ev := models.RealtimeEvent{
			ID:         id,
			Type:       eventType,
			EntityType: entityType,
			EntityId:   entityId,
			Payload:    payload,
			CreatedAt:  createdAt.Format(time.RFC3339),
		}
		Hub.Broadcast(ev)
	}
}

func GetEventsSince(db *sql.DB, sinceID int64, limit int) ([]models.RealtimeEvent, error) {
	if limit <= 0 {
		limit = 100
	}
	if limit > 500 {
		limit = 500
	}

	rows, err := db.Query(`
        SELECT id, type, entity_type, entity_id, payload, created_at
        FROM realtime_events
        WHERE id > $1
        ORDER BY id ASC
        LIMIT $2
    `, sinceID, limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	events := make([]models.RealtimeEvent, 0)
	for rows.Next() {
		var ev models.RealtimeEvent
		var payloadStr string
		var createdAt time.Time
		if err := rows.Scan(&ev.ID, &ev.Type, &ev.EntityType, &ev.EntityId, &payloadStr, &createdAt); err != nil {
			return nil, err
		}
		ev.CreatedAt = createdAt.Format(time.RFC3339)
		_ = json.Unmarshal([]byte(payloadStr), &ev.Payload)
		if ev.Payload == nil {
			ev.Payload = make(map[string]interface{})
		}
		events = append(events, ev)
	}
	return events, nil
}
