{"file_text":"package services

import (
	"database/sql"
	"encoding/json"
	"errors"
	"math"
	"time"

	"github.com/google/uuid"
	"labsystem/internal/models"
)

func HaversineDistance(lat1, lon1, lat2, lon2 float64) float64 {
	const R = 6371.0 // Earth radius in km
	dLat := (lat2 - lat1) * math.Pi / 180.0
	dLon := (lon2 - lon1) * math.Pi / 180.0
	a := math.Sin(dLat/2)*math.Sin(dLat/2) +
		math.Cos(lat1*math.Pi/180.0)*math.Cos(lat2*math.Pi/180.0)*
			math.Sin(dLon/2)*math.Sin(dLon/2)
	c := 2 * math.Atan2(math.Sqrt(a), math.Sqrt(1-a))
	return R * c
}

type RoutePath struct {
	LabId            string
	TotalDurationMin int
	TotalCost        float64
	NodeIds          []string
	ConnectionIds    []string
	EstimatedArrival time.Time
}

func CheckServiceability(db *sql.DB, origin models.Coordinate, originType, originNodeId, sampleTypeId string, requestedAt, deadline, earliest, latest time.Time) (bool, string, *string, *time.Time, int, error) {
	// Validate times
	if deadline.Before(requestedAt) {
		return false, "invalid_deadline", nil, nil, 0, errors.New("invalid_deadline")
	}
	if !earliest.IsZero() && !latest.IsZero() && latest.Before(earliest) {
		return false, "invalid_collection_window", nil, nil, 0, errors.New("invalid_collection_window")
	}

	st, err := GetSampleType(db, sampleTypeId)
	if err != nil {
		return false, "not_found", nil, nil, 0, errors.New("not_found")
	}

	snap, err := GetLatestSnapshot(db)
	version := 1
	if err == nil && snap != nil {
		version = snap.Version
	}

	// 1. Find origin collection node
	type nodeInfo struct {
		id              string
		name            string
		lat             float64
		lng             float64
		coverageKm      float64
		handlingMin     int
		active          bool
		isColl          bool
		isTrans         bool
		isHub           bool
		isLab           bool
		capUnits        int
		resUnits        int
		cooledCapUnits  int
		cooledResUnits  int
		acceptedSamples []string
	}

	rows, err := db.Query(`
        SELECT id, name, latitude, longitude, coverage_km, handling_minutes, active,
               function_collection_point, function_transfer_point, function_hub, function_laboratory,
               capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units, accepted_sample_types
        FROM locations
    `)
	if err != nil {
		return false, "", nil, nil, version, err
	}
	defer rows.Close()

	nodes := make(map[string]nodeInfo)
	var originNode *nodeInfo
	minDist := math.MaxFloat64

	for rows.Next() {
		var n nodeInfo
		if err := rows.Scan(&n.id, &n.name, &n.lat, &n.lng, &n.coverageKm, &n.handlingMin, &n.active,
			&n.isColl, &n.isTrans, &n.isHub, &n.isLab,
			&n.capUnits, &n.resUnits, &n.cooledCapUnits, &n.cooledResUnits, &n.acceptedSamples); err != nil {
			return false, "", nil, nil, version, err
		}
		nodes[n.id] = n

		if originNodeId != "" && n.id == originNodeId && n.active {
			temp := n
			originNode = &temp
		} else if originNodeId == "" && n.active && n.isColl {
			dist := HaversineDistance(origin.Latitude, origin.Longitude, n.lat, n.lng)
			if dist <= n.coverageKm && dist < minDist {
				minDist = dist
				temp := n
				originNode = &temp
			}
		}
	}

	if originNode == nil {
		return false, models.ReasonOutsideServiceCoverage, nil, nil, version, nil
	}

	// 2. Find accepting active laboratories
	var candidateLabs []nodeInfo
	for _, n := range nodes {
		if n.active && n.isLab {
			for _, acc := range n.acceptedSamples {
				if acc == sampleTypeId {
					candidateLabs = append(candidateLabs, n)
					break
				}
			}
		}
	}

	if len(candidateLabs) == 0 {
		return false, models.ReasonNoAcceptingLaboratory, nil, nil, version, nil
	}

	// 3. Load active connections
	type connInfo struct {
		id             string
		fromId         string
		toId           string
		travelMin      int
		cost           float64
		cooled         bool
		active         bool
		capUnits       int
		resUnits       int
		cooledCapUnits int
		cooledResUnits int
	}

	cRows, err := db.Query(`
        SELECT id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active,
               capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
        FROM connections
        WHERE active = true
    `)
	if err != nil {
		return false, "", nil, nil, version, err
	}
	defer cRows.Close()

	adj := make(map[string][]connInfo)
	for cRows.Next() {
		var c connInfo
		if err := cRows.Scan(&c.id, &c.fromId, &c.toId, &c.travelMin, &c.cost, &c.cooled, &c.active,
			&c.capUnits, &c.resUnits, &c.cooledCapUnits, &c.cooledResUnits); err != nil {
			return false, "", nil, nil, version, err
		}
		adj[c.fromId] = append(adj[c.fromId], c)
	}

	// 4. Search routes to candidate labs
	collectionStartTime := requestedAt
	if !earliest.IsZero() {
		collectionStartTime = earliest
	}
	collectionDwell := 15

	hadCapacityIssue := false
	hadDeadlineIssue := false
	var bestRoute *RoutePath

	for _, targetLab := range candidateLabs {
		// If origin node IS the target laboratory
		if originNode.id == targetLab.id {
			// Check lab capacity
			if st.RequiresCooledRoute {
				if targetLab.cooledCapUnits-targetLab.cooledResUnits <= 0 {
					hadCapacityIssue = true
					continue
				}
			} else {
				if targetLab.capUnits-targetLab.resUnits <= 0 {
					hadCapacityIssue = true
					continue
				}
			}

			arrTime := collectionStartTime.Add(time.Duration(collectionDwell+targetLab.handlingMin) * time.Minute)
			if arrTime.After(deadline) {
				hadDeadlineIssue = true
				continue
			}

			route := &RoutePath{
				LabId:            targetLab.id,
				TotalDurationMin: collectionDwell + targetLab.handlingMin,
				TotalCost:        0,
				NodeIds:          []string{originNode.id},
				ConnectionIds:    []string{},
				EstimatedArrival: arrTime,
			}
			if bestRoute == nil || route.TotalDurationMin < bestRoute.TotalDurationMin {
				bestRoute = route
			}
			continue
		}

		// BFS to find paths from originNode.id to targetLab.id
		type queueItem struct {
			nodeId        string
			duration      int
			cost          float64
			pathNodes     []string
			pathConns     []string
			visitedNodes  map[string]bool
			capacityIssue bool
		}

		initVisited := map[string]bool{originNode.id: true}
		queue := []queueItem{{
			nodeId:        originNode.id,
			duration:      collectionDwell + originNode.handlingMin,
			cost:          0,
			pathNodes:     []string{originNode.id},
			pathConns:     []string{},
			visitedNodes:  initVisited,
			capacityIssue: false,
		}}

		for len(queue) > 0 {
			curr := queue[0]
			queue = queue[1:]

			if curr.nodeId == targetLab.id {
				if curr.capacityIssue {
					hadCapacityIssue = true
					continue
				}
				arrTime := collectionStartTime.Add(time.Duration(curr.duration) * time.Minute)
				if arrTime.After(deadline) {
					hadDeadlineIssue = true
					continue
				}
				route := &RoutePath{
					LabId:            targetLab.id,
					TotalDurationMin: curr.duration,
					TotalCost:        curr.cost,
					NodeIds:          curr.pathNodes,
					ConnectionIds:    curr.pathConns,
					EstimatedArrival: arrTime,
				}
				if bestRoute == nil || route.TotalDurationMin < bestRoute.TotalDurationMin {
					bestRoute = route
				}
				continue
			}

			// Explore neighbors
			for _, conn := range adj[curr.nodeId] {
				if curr.visitedNodes[conn.toId] {
					continue
				}
				nextNode, exists := nodes[conn.toId]
				if !exists || !nextNode.active {
					continue
				}
				// Intermediate nodes must be transfer_point, hub, or laboratory
				if nextNode.id != targetLab.id && !nextNode.isTrans && !nextNode.isHub && !nextNode.isLab {
					continue
				}

				capIssue := curr.capacityIssue
				// Check connection capacity & cooling
				if st.RequiresCooledRoute {
					if !conn.cooled || conn.cooledCapUnits-conn.cooledResUnits <= 0 {
						capIssue = true
					}
					if nextNode.cooledCapUnits-nextNode.cooledResUnits <= 0 {
						capIssue = true
					}
				} else {
					if conn.capUnits-conn.resUnits <= 0 {
						capIssue = true
					}
					if nextNode.capUnits-nextNode.resUnits <= 0 {
						capIssue = true
					}
				}

				newVisited := make(map[string]bool)
				for k, v := range curr.visitedNodes {
					newVisited[k] = v
				}
				newVisited[nextNode.id] = true

				newNodes := append([]string{}, curr.pathNodes...)
				newNodes = append(newNodes, nextNode.id)

				newConns := append([]string{}, curr.pathConns...)
				newConns = append(newConns, conn.id)

				queue = append(queue, queueItem{
					nodeId:        nextNode.id,
					duration:      curr.duration + conn.travelMin + nextNode.handlingMin,
					cost:          curr.cost + conn.cost,
					pathNodes:     newNodes,
					pathConns:     newConns,
					visitedNodes:  newVisited,
					capacityIssue: capIssue,
				})
			}
		}
	}

	if bestRoute != nil {
		return true, models.ReasonServiceable, &bestRoute.LabId, &bestRoute.EstimatedArrival, version, nil
	}

	if hadCapacityIssue {
		return false, models.ReasonInsufficientCapacity, nil, nil, version, nil
	}
	if hadDeadlineIssue {
		return false, models.ReasonDeadlineUnreachable, nil, nil, version, nil
	}

	return false, models.ReasonNoRoute, nil, nil, version, nil
}

func GetLatestSnapshot(db *sql.DB) (*models.ServiceabilitySnapshotData, error) {
	var snap models.ServiceabilitySnapshotData
	var regionsJSON string
	var computedAt time.Time

	err := db.QueryRow(`
        SELECT version, status, computed_at, network_revision, active_collection_point_count, regions
        FROM serviceability_snapshots
        ORDER BY version DESC
        LIMIT 1
    `).Scan(&snap.Version, &snap.Status, &computedAt, &snap.NetworkRevision, &snap.ActiveCollectionPointCount, &regionsJSON)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, nil
		}
		return nil, err
	}

	snap.ComputedAt = computedAt.Format(time.RFC3339)
	_ = json.Unmarshal([]byte(regionsJSON), &snap.Regions)
	if snap.Regions == nil {
		snap.Regions = []models.ServiceabilityRegion{}
	}

	return &snap, nil
}

func RecomputeAndPublishSnapshot(db *sql.DB) error {
	rows, err := db.Query(`
        SELECT id, name, latitude, longitude, coverage_km
        FROM locations
        WHERE active = true AND function_collection_point = true
    `)
	if err != nil {
		return err
	}
	defer rows.Close()

	var regions []models.ServiceabilityRegion
	for rows.Next() {
		var r models.ServiceabilityRegion
		if err := rows.Scan(&r.LocationId, &r.Name, &r.Latitude, &r.Longitude, &r.CoverageKm); err != nil {
			return err
		}
		regions = append(regions, r)
	}

	var latestVersion int
	_ = db.QueryRow("SELECT COALESCE(MAX(version), 0) FROM serviceability_snapshots").Scan(&latestVersion)
	newVersion := latestVersion + 1

	regBytes, _ := json.Marshal(regions)
	netRev := uuid.New().String()

	_, err = db.Exec(`
        INSERT INTO serviceability_snapshots (version, status, computed_at, network_revision, active_collection_point_count, regions)
        VALUES ($1, 'published', NOW(), $2, $3, $4)
    `, newVersion, netRev, len(regions), string(regBytes))

	return err
}
