{"file_text":"package services

import (
	"database/sql"
	"errors"
	"time"

	"github.com/google/uuid"
	"labsystem/internal/models"
)

var (
	ErrHandoffNotFound = errors.New("not_found")
	ErrCustodyMismatch = errors.New("custody_mismatch")
	ErrInvalidHandoff  = errors.New("invalid_handoff")
)

type HandoffResult struct {
	HandoffId        string
	SampleId         string
	Status           string
	SenderConfirmed  bool
	ReceiverConfirmed bool
	CurrentHolderId  string
}

func InitiateHandoff(db *sql.DB, sampleId, fromAssignmentId, toAssignmentId, senderId, receiverId string, initiatedAt time.Time, actorId, actorRole string) (*HandoffResult, error) {
	// Verify current sample holder
	var currentHolderId sql.NullString
	var sampleStatus string
	err := db.QueryRow("SELECT current_holder_id, status FROM samples WHERE id = $1", sampleId).Scan(&currentHolderId, &sampleStatus)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, errors.New("not_found")
		}
		return nil, err
	}

	if currentHolderId.Valid && currentHolderId.String != senderId {
		return nil, ErrCustodyMismatch
	}

	// Check if already exists
	var existingId string
	var status string
	var sConf, rConf bool
	var currHold string
	err = db.QueryRow(`
        SELECT id, status, sender_confirmed, receiver_confirmed, current_holder_id
        FROM handoffs
        WHERE sample_id = $1 AND from_assignment_id = $2 AND to_assignment_id = $3
    `, sampleId, fromAssignmentId, toAssignmentId).Scan(&existingId, &status, &sConf, &rConf, &currHold)
	if err == nil {
		return &HandoffResult{
			HandoffId:         existingId,
			SampleId:          sampleId,
			Status:            status,
			SenderConfirmed:   sConf,
			ReceiverConfirmed: rConf,
			CurrentHolderId:   currHold,
		}, nil
	}

	handoffId := uuid.New().String()
	holder := senderId
	if currentHolderId.Valid {
		holder = currentHolderId.String
	}

	_, err = db.Exec(`
        INSERT INTO handoffs (id, sample_id, from_assignment_id, to_assignment_id, sender_id, receiver_id, current_holder_id, status, sender_confirmed, sender_confirmed_at, receiver_confirmed, created_at)
        VALUES ($1, $2, $3, $4, $5, $6, $7, 'pending', true, $8, false, NOW())
    `, handoffId, sampleId, fromAssignmentId, toAssignmentId, senderId, receiverId, holder, initiatedAt)
	if err != nil {
		return nil, err
	}

	_, _ = db.Exec(`
        UPDATE samples
        SET pending_handoff_id = $1, updated_at = NOW()
        WHERE id = $2
    `, handoffId, sampleId)

	RecordAudit(db, actorId, actorRole, actorRole, "handoff_initiated", "handoff", handoffId, true, map[string]interface{}{
		"sampleId":         sampleId,
		"fromAssignmentId": fromAssignmentId,
		"toAssignmentId":   toAssignmentId,
		"senderId":         senderId,
		"receiverId":       receiverId,
	})

	BroadcastEvent(db, "handoff_initiated", "handoff", handoffId, map[string]interface{}{
		"sampleId":   sampleId,
		"senderId":   senderId,
		"receiverId": receiverId,
	})

	return &HandoffResult{
		HandoffId:         handoffId,
		SampleId:          sampleId,
		Status:            "pending",
		SenderConfirmed:   true,
		ReceiverConfirmed: false,
		CurrentHolderId:   holder,
	}, nil
}

func ConfirmHandoff(db *sql.DB, handoffId, userId, side string, confirmedAt time.Time, actorId, actorRole string) (*HandoffResult, error) {
	var h struct {
		id               string
		sampleId         string
		fromAssignmentId string
		toAssignmentId   string
		senderId         string
		receiverId       string
		currentHolderId  string
		status           string
		senderConfirmed  bool
		receiverConfirmed bool
	}

	err := db.QueryRow(`
        SELECT id, sample_id, from_assignment_id, to_assignment_id, sender_id, receiver_id, current_holder_id, status, sender_confirmed, receiver_confirmed
        FROM handoffs
        WHERE id = $1
    `, handoffId).Scan(
		&h.id, &h.sampleId, &h.fromAssignmentId, &h.toAssignmentId, &h.senderId, &h.receiverId,
		&h.currentHolderId, &h.status, &h.senderConfirmed, &h.receiverConfirmed,
	)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, ErrHandoffNotFound
		}
		return nil, err
	}

	if h.status == "completed" {
		return &HandoffResult{
			HandoffId:         h.id,
			SampleId:          h.sampleId,
			Status:            "completed",
			SenderConfirmed:   true,
			ReceiverConfirmed: true,
			CurrentHolderId:   h.receiverId,
		}, nil
	}

	if side == "sender" {
		if userId != "" && userId != h.senderId {
			return nil, ErrCustodyMismatch
		}
		h.senderConfirmed = true
		_, _ = db.Exec("UPDATE handoffs SET sender_confirmed = true, sender_confirmed_at = $1, updated_at = NOW() WHERE id = $2", confirmedAt, handoffId)
	} else if side == "receiver" {
		if userId != "" && userId != h.receiverId {
			return nil, ErrCustodyMismatch
		}
		h.receiverConfirmed = true
		_, _ = db.Exec("UPDATE handoffs SET receiver_confirmed = true, receiver_confirmed_at = $1, updated_at = NOW() WHERE id = $2", confirmedAt, handoffId)
	} else {
		// Side not specified, match userId
		if userId == h.senderId {
			h.senderConfirmed = true
			_, _ = db.Exec("UPDATE handoffs SET sender_confirmed = true, sender_confirmed_at = $1, updated_at = NOW() WHERE id = $2", confirmedAt, handoffId)
		} else if userId == h.receiverId {
			h.receiverConfirmed = true
			_, _ = db.Exec("UPDATE handoffs SET receiver_confirmed = true, receiver_confirmed_at = $1, updated_at = NOW() WHERE id = $2", confirmedAt, handoffId)
		}
	}

	// If both confirmed -> complete transfer of custody
	if h.senderConfirmed && h.receiverConfirmed {
		h.status = "completed"
		h.currentHolderId = h.receiverId

		_, _ = db.Exec(`
            UPDATE handoffs
            SET status = 'completed', current_holder_id = $1, updated_at = NOW()
            WHERE id = $2
        `, h.receiverId, handoffId)

		_, _ = db.Exec(`
            UPDATE samples
            SET current_holder_id = $1, pending_handoff_id = NULL, updated_at = NOW()
            WHERE id = $2
        `, h.receiverId, h.sampleId)

		_, _ = db.Exec(`
            UPDATE journey_legs
            SET status = 'completed', completed_at = $1, updated_at = NOW()
            WHERE id = $2
        `, confirmedAt, h.fromAssignmentId)

		_, _ = db.Exec(`
            UPDATE journey_legs
            SET status = 'in_transit', updated_at = NOW()
            WHERE id = $1
        `, h.toAssignmentId)

		RecordAudit(db, actorId, actorRole, actorRole, "custody_transferred", "sample", h.sampleId, true, map[string]interface{}{
			"handoffId":   handoffId,
			"senderId":    h.senderId,
			"receiverId":  h.receiverId,
			"transferred": true,
		})

		BroadcastEvent(db, "custody_transferred", "sample", h.sampleId, map[string]interface{}{
			"handoffId":  handoffId,
			"receiverId": h.receiverId,
		})
	}

	return &HandoffResult{
		HandoffId:         h.id,
		SampleId:          h.sampleId,
		Status:            h.status,
		SenderConfirmed:   h.senderConfirmed,
		ReceiverConfirmed: h.receiverConfirmed,
		CurrentHolderId:   h.currentHolderId,
	}, nil
}
