func CreateCollectionRequest(db *sql.DB, requesterId string, origin models.Coordinate, originType, originNodeId, sampleTypeId string, requestedAt, deadline, earliest, latest time.Time, actorId, actorRole string) (*models.SampleState, *models.JourneyPlan, error) {
