	if !serviceable {
		initStatus = "unserviceable"
	}

	_, err = db.Exec(`
        INSERT INTO samples (id, request_id, requester_id, sample_type_id, status, sealed, target_laboratory_id, latest_latitude, latest_longitude, location_recorded_at)
        VALUES ($1, $2, $3, $4, $5, false, $6, $7, $8, NOW())
    `, sampleId, requestId, requesterId, sampleTypeId, initStatus, labIdPtr, origin.Latitude, origin.Longitude)
	if err != nil {
		return nil, nil, err
	}

	RecordAudit(db, actorId, actorRole, actorRole, "collection_request_created", "collection_request", requestId, true, map[string]interface{}{
