func (h *AuthHandlers) HandleCreateUser(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Username           string                 `json:"username"`
		Password           string                 `json:"password"`
		Email              *string                `json:"email,omitempty"`
		FullName           *string                `json:"fullName,omitempty"`
		Phone              *string                `json:"phone,omitempty"`
		Roles              []string               `json:"roles"`
		Qualifications     []string               `json:"qualifications,omitempty"`
		Certifications     []models.Certification `json:"certifications,omitempty"`
		AssignedLocationId *string                `json:"assignedLocationId,omitempty"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_request", "Invalid request body")
		return
	}

	if req.Username == "" || req.Password == "" || len(req.Roles) == 0 {
		WriteError(w, http.StatusBadRequest, "invalid_request", "Username, password and at least one role are required")
		return
	}

	currUser := GetUserFromContext(r)
	actorId := "system"
	actorRole := models.RoleAdministrator
	if currUser != nil {
		actorId = currUser.ID
		actorRole = GetActiveRoleFromContext(r)
	}

	newUser := models.User{
		Username:           req.Username,
		Email:              req.Email,
		FullName:           req.FullName,
		Phone:              req.Phone,
		Roles:              req.Roles,
		Qualifications:     req.Qualifications,
		Certifications:     req.Certifications,
		Active:             true,
		AssignedLocationId: req.AssignedLocationId,
	}

	created, err := services.CreateUser(h.DB, newUser, req.Password, actorId, actorRole)
	if err != nil {
		if err == services.ErrUsernameExists {
			WriteError(w, http.StatusConflict, "username_exists", "Username already exists")
			return
		}
		WriteError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}

	WriteJSON(w, http.StatusCreated, map[string]interface{}{
		"id":                 created.ID,
		"username":           created.Username,
		"fullName":           created.FullName,
		"email":              created.Email,
		"phone":              created.Phone,
		"roles":              created.Roles,
		"qualifications":     created.Qualifications,
		"certifications":     created.Certifications,
		"active":             created.Active,
		"assignedLocationId": created.AssignedLocationId,
	})
}

func (h *AuthHandlers) HandleUpdateUserAccess(w http.ResponseWriter, r *http.Request) {
	// Extract userId from URL path: /api/admin/users/{userId}/access
	parts := strings.Split(r.URL.Path, "/")
	var userId string
	for i, p := range parts {
		if p == "users" && i+1 < len(parts) {
			userId = parts[i+1]
			break
		}
	}

	if userId == "" {
		WriteError(w, http.StatusBadRequest, "invalid_request", "User ID is required")
		return
	}

	var req struct {
		Roles              []string               `json:"roles"`
		Qualifications     []string               `json:"qualifications,omitempty"`
		Certifications     []models.Certification `json:"certifications,omitempty"`
		Active             *bool                  `json:"active,omitempty"`
		AssignedLocationId *string                `json:"assignedLocationId,omitempty"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_request", "Invalid request body")
		return
	}

	currUser := GetUserFromContext(r)
	actorId := "system"
	actorRole := models.RoleAdministrator
	if currUser != nil {
		actorId = currUser.ID
		actorRole = GetActiveRoleFromContext(r)
	}

	active := true
	if req.Active != nil {
		active = *req.Active
	}

	updated, err := services.UpdateUserAccess(h.DB, userId, req.Roles, req.Qualifications, req.Certifications, active, req.AssignedLocationId, actorId, actorRole)
	if err != nil {
		if err == services.ErrUserNotFound {
			WriteError(w, http.StatusNotFound, "not_found", "User not found")
