{"summary":"Create serviceability API handlers","path":"/workspace/backend/internal/api/handlers_serviceability.go","command":"create","file_text":"package api

import (
	"database/sql"
	"encoding/json"
	"net/http"
	"time"

	"labsystem/internal/models"
	"labsystem/internal/services"
)

type ServiceabilityHandlers struct {
	DB *sql.DB
}

func (h *ServiceabilityHandlers) HandleCheck(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Origin               models.Coordinate `json:"origin"`
		OriginType           string            `json:"originType"`
		OriginNodeId         *string           `json:"originNodeId,omitempty"`
		SampleTypeId         string            `json:"sampleTypeId"`
		RequestedAt          string            `json:"requestedAt"`
		DeliveryDeadline     string            `json:"deliveryDeadline"`
		EarliestCollectionAt *string           `json:"earliestCollectionAt,omitempty"`
		LatestCollectionAt   *string           `json:"latestCollectionAt,omitempty"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_request", "Invalid request body")
		return
	}

	reqTime, err := time.Parse(time.RFC3339, req.RequestedAt)
	if err != nil {
		reqTime = time.Now()
	}

	deadTime, err := time.Parse(time.RFC3339, req.DeliveryDeadline)
	if err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_deadline", "Invalid delivery deadline format")
		return
	}

	var earliest, latest time.Time
	if req.EarliestCollectionAt != nil {
		earliest, _ = time.Parse(time.RFC3339, *req.EarliestCollectionAt)
	}
	if req.LatestCollectionAt != nil {
		latest, _ = time.Parse(time.RFC3339, *req.LatestCollectionAt)
	}

	origNodeId := ""
	if req.OriginNodeId != nil {
		origNodeId = *req.OriginNodeId
	}

	serviceable, reason, labIdPtr, estArrPtr, version, err := services.CheckServiceability(h.DB, req.Origin, req.OriginType, origNodeId, req.SampleTypeId, reqTime, deadTime, earliest, latest)
	if err != nil {
		if err.Error() == "invalid_deadline" {
			WriteError(w, http.StatusBadRequest, "invalid_deadline", "Deadline must be after requested time")
			return
		}
		if err.Error() == "invalid_collection_window" {
			WriteError(w, http.StatusBadRequest, "invalid_collection_window", "Earliest collection time must be before latest collection time")
			return
		}
		if err.Error() == "not_found" {
			WriteError(w, http.StatusNotFound, "not_found", "Sample type not found")
			return
		}
		WriteError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}

	res := map[string]interface{}{
		"serviceable": serviceable,
		"reason":      reason,
		"version":     version,
	}
	if labIdPtr != nil {
		res["targetLaboratoryId"] = *labIdPtr
	}
	if estArrPtr != nil {
		res["estimatedArrivalAt"] = estArrPtr.Format(time.RFC3339)
	}

	WriteJSON(w, http.StatusOK, res)
}

func (h *ServiceabilityHandlers) HandleGetSnapshot(w http.ResponseWriter, r *http.Request) {
	snap, err := services.GetLatestSnapshot(h.DB)
	if err != nil {
		WriteError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if snap == nil {
		WriteJSON(w, http.StatusOK, map[string]interface{}{
			"version":                    1,
			"status":                     "published",
			"computedAt":                 time.Now().Format(time.RFC3339),
			"networkRevision":            "init",
			"regions":                    []models.ServiceabilityRegion{},
			"activeCollectionPointCount": 0,
		})
		return
	}

	WriteJSON(w, http.StatusOK, snap)
}

func (h *ServiceabilityHandlers) HandlePublishSnapshot(w http.ResponseWriter, r *http.Request) {
	user := GetUserFromContext(r)
	role := GetActiveRoleFromContext(r)

	err := services.RecomputeAndPublishSnapshot(h.DB)
	if err != nil {
		WriteError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}

	snap, err := services.GetLatestSnapshot(h.DB)
	if err != nil {
		WriteError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}

	services.RecordAudit(h.DB, user.ID, role, role, "serviceability_snapshot_published", "serviceability_snapshot", "snapshot", true, map[string]interface{}{
		"version": snap.Version,
	})

	WriteJSON(w, http.StatusOK, snap)
}
"}

