                content = resp.get("content", {}).get("application/json", {})
                schema = content.get("schema", {})
                props = list(schema.get("properties", {}).keys())
                req = schema.get("required", [])
                has_data = "data" in props
                data_props = []
                if has_data:
                    data_schema = schema["properties"]["data"]
                    if "$ref" in data_schema:
                        data_props = f"ref:{data_schema['$ref']}"
                    elif data_schema.get("type") == "array":
                        data_props = f"array_of:{data_schema.get('items', {}).get('$ref', data_schema.get('items', {}).get('type'))}"
                    else:
                        data_props = list(data_schema.get("properties", {}).keys())
                print(f"{method.upper()} {path} -> {code}: data_prop={has_data}, data_shape={data_props}")
