	user := GetUserFromContext(r)
	role := GetActiveRoleFromContext(r)

	recTime, err := time.Parse(time.RFC3339, req.RecordedAt)
	if err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_time", "Invalid recordedAt format")
		return
	}

	result, err := services.RecordWorkerLocation(h.DB, req.AssignmentId, user.ID, req.Coordinate, req.Sequence, recTime, role)
	if err != nil {
		if err == services.ErrAssignmentNotFound {
			WriteError(w, http.StatusNotFound, "not_found", "Assignment not found")
