{"path":"/workspace/backend/internal/api/handlers_audit_events.go","command":"create","summary":"Create audit and events handlers","file_text":"package api

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"net/http"
	"strconv"
	"time"

	"labsystem/internal/models"
	"labsystem/internal/services"
)

type AuditEventHandlers struct {
	DB *sql.DB
}

func (h *AuditEventHandlers) HandleSearchAuditTrail(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Query      *string `json:"query,omitempty"`
		ActorId    *string `json:"actorId,omitempty"`
		EntityType *string `json:"entityType,omitempty"`
		EntityId   *string `json:"entityId,omitempty"`
		Action     *string `json:"action,omitempty"`
		Role       *string `json:"role,omitempty"`
		Success    *bool   `json:"success,omitempty"`
		FromTime   *string `json:"fromTime,omitempty"`
		ToTime     *string `json:"toTime,omitempty"`
		Limit      *int    `json:"limit,omitempty"`
		Offset     *int    `json:"offset,omitempty"`
		Order      *string `json:"order,omitempty"`
	}
	_ = json.NewDecoder(r.Body).Decode(&req)

	user := GetUserFromContext(r)
	role := GetActiveRoleFromContext(r)

	var fromTime, toTime *time.Time
	if req.FromTime != nil && *req.FromTime != "" {
		if t, err := time.Parse(time.RFC3339, *req.FromTime); err == nil {
			fromTime = &t
		}
	}
	if req.ToTime != nil && *req.ToTime != "" {
		if t, err := time.Parse(time.RFC3339, *req.ToTime); err == nil {
			toTime = &t
		}
	}

	limit := 50
	if req.Limit != nil && *req.Limit > 0 {
		limit = *req.Limit
	}
	offset := 0
	if req.Offset != nil && *req.Offset >= 0 {
		offset = *req.Offset
	}
	order := "desc"
	if req.Order != nil && *req.Order == "asc" {
		order = "asc"
	}

	result, err := services.SearchAuditTrail(h.DB, req.Query, req.ActorId, req.EntityType, req.EntityId, req.Action, req.Role, req.Success, fromTime, toTime, limit, offset, order, user.ID, role)
	if err != nil {
		if err == services.ErrForbidden {
			WriteError(w, http.StatusForbidden, "forbidden", "Forbidden")
			return
		}
		WriteError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}

	WriteJSON(w, http.StatusOK, map[string]interface{}{
		"data": result,
	})
}

func (h *AuditEventHandlers) HandleStreamEvents(w http.ResponseWriter, r *http.Request) {
	sinceStr := r.URL.Query().Get("since")
	var since int64 = 0
	if sinceStr != "" {
		if s, err := strconv.ParseInt(sinceStr, 10, 64); err == nil {
			since = s
		}
	}

	// Check if SSE requested
	accept := r.Header.Get("Accept")
	if accept == "text/event-stream" {
		flusher, ok := w.(http.Flusher)
		if !ok {
			WriteError(w, http.StatusInternalServerError, "internal_error", "Streaming unsupported")
			return
		}

		w.Header().Set("Content-Type", "text/event-stream")
		w.Header().Set("Cache-Control", "no-cache")
		w.Header().Set("Connection", "keep-alive")
		w.Header().Set("Access-Control-Allow-Origin", "*")

		currentCursor := since
		// Poll loop for SSE
		ticker := time.NewTicker(1 * time.Second)
		defer ticker.Stop()

		for {
			select {
			case <-r.Context().Done():
				return
			case <-ticker.C:
				events, maxCursor, err := services.GetEventsSince(h.DB, currentCursor)
				if err == nil && len(events) > 0 {
					currentCursor = maxCursor
					for _, ev := range events {
						data, _ := json.Marshal(ev)
						fmt.Fprintf(w, "data: %s\n\n", string(data))
					}
					flusher.Flush()
				}
			}
		}
	}

	// Regular JSON response
	events, maxCursor, err := services.GetEventsSince(h.DB, since)
	if err != nil {
		WriteError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if events == nil {
		events = []models.RealtimeEvent{}
	}

	WriteJSON(w, http.StatusOK, map[string]interface{}{
		"data": map[string]interface{}{
			"events": events,
			"cursor": maxCursor,
		},
	})
}

func (h *AuditEventHandlers) HandleReady(w http.ResponseWriter, r *http.Request) {
	err := h.DB.Ping()
	if err != nil {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusServiceUnavailable)
		json.NewEncoder(w).Encode(map[string]string{"status": "starting"})
		return
	}

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	json.NewEncoder(w).Encode(map[string]string{"status": "ready"})
}
"}

{"file_text":"package api

import (
	"database/sql"
	"net/http"
	"os"
	"path/filepath"
	"strings"

	"github.com/go-chi/chi/v5"
	chimiddleware "github.com/go-chi/chi/v5/middleware"

	"labsystem/internal/models"
)

func SetupRouter(db *sql.DB) *chi.Mux {
	r := chi.NewRouter()

	r.Use(chimiddleware.RequestID)
	r.Use(chimiddleware.RealIP)
	r.Use(chimiddleware.Logger)
	r.Use(chimiddleware.Recoverer)

	// CORS middleware
	r.Use(func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, req *http.Request) {
			w.Header().Set("Access-Control-Allow-Origin", "*")
			w.Header().Set("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE, OPTIONS")
			w.Header().Set("Access-Control-Allow-Headers", "Accept, Authorization, Content-Type, X-CSRF-Token, Sec-WebSocket-Protocol")
			if req.Method == "OPTIONS" {
				w.WriteHeader(http.StatusOK)
				return
			}
			next.ServeHTTP(w, req)
		})
	})

	authH := &AuthHandlers{DB: db}
	netH := &NetworkHandlers{DB: db}
	servH := &ServiceabilityHandlers{DB: db}
	sampH := &SampleHandlers{DB: db}
	handH := &HandoffHandlers{DB: db}
	workH := &WorkDispatchHandlers{DB: db}
	jourH := &JourneyHandlers{DB: db}
	audH := &AuditEventHandlers{DB: db}

	// Readiness check
	r.Get("/ready", audH.HandleReady)

	// Map assets static file server
	mapAssetsDir := "/opt/arena/map-assets"
	if _, err := os.Stat(mapAssetsDir); err == nil {
		fs := http.StripPrefix("/map-assets/", http.FileServer(http.Dir(mapAssetsDir)))
		r.Handle("/map-assets/*", fs)
	}

	// Public / Unauthenticated API routes
	r.Post("/api/authenticate-user", authH.HandleAuthenticateUser)
	r.Post("/api/check-serviceability", servH.HandleCheck)
	r.Post("/api/read-serviceability-snapshot", servH.HandleReadSnapshot)

	// Authenticated API routes
	r.Group(func(authGroup chi.Router) {
		authGroup.Use(AuthMiddleware(db))

		// User & Role Context
		authGroup.Post("/api/select-active-role", authH.HandleSelectActiveRole)
		authGroup.Get("/api/read-user/{userId}", authH.HandleReadUser)
		authGroup.Get("/api/ui/bootstrap", workH.HandleBootstrap)

		// Realtime events
		authGroup.Get("/api/events", audH.HandleStreamEvents)

		// Samples & Lifecycle
		authGroup.Get("/api/read-sample-state/{sampleId}", sampH.HandleReadSampleState)
		authGroup.Post("/api/read-sample-lifecycle", sampH.HandleReadSampleLifecycle)
		authGroup.Post("/api/record-handling-checkpoint", sampH.HandleRecordHandlingCheckpoint)
		authGroup.Post("/api/record-worker-location", sampH.HandleRecordWorkerLocation)
		authGroup.Post("/api/update-assignment-progress", sampH.HandleUpdateAssignmentProgress)

		// Handoffs
		authGroup.Post("/api/initiate-handoff", handH.HandleInitiateHandoff)
		authGroup.Post("/api/confirm-handoff", handH.HandleConfirmHandoff)

		// Work & Assignments
		authGroup.Post("/api/list-role-work", workH.HandleListRoleWork)
		authGroup.Post("/api/accept-assignment", workH.HandleAcceptAssignment)
		authGroup.Post("/api/decline-assignment", workH.HandleDeclineAssignment)
		authGroup.Post("/api/set-worker-availability", workH.HandleSetWorkerAvailability)
		authGroup.Post("/api/read-journey-plan", jourH.HandleReadJourneyPlan)

		// Requester & Collector actions
		authGroup.Post("/api/create-collection-request", sampH.HandleCreateCollectionRequest)
		authGroup.Post("/api/ingest-presealed-sample", sampH.HandleIngestPresealedSample)
		authGroup.Post("/api/collect-and-seal-sample", sampH.HandleCollectAndSealSample)

		// Laboratory actions
		authGroup.Post("/api/confirm-laboratory-receipt", sampH.HandleConfirmLaboratoryReceipt)
		authGroup.Post("/api/record-laboratory-exception", sampH.HandleRecordLaboratoryException)

		// Capacity config (node handler, lab intake, dispatcher, admin)
		authGroup.Post("/api/configure-capacity", netH.HandleConfigureCapacity)

		// Dispatcher & Admin actions
		authGroup.Group(func(dispatchGroup chi.Router) {
			dispatchGroup.Use(RoleMiddleware(models.RoleDispatcher, models.RoleAdministrator))

