{"file_text":"package services

import (
	"context"
	"database/sql"
	"log"
	"time"

	"labsystem/internal/models"
)

func StartOfferExpirationWorker(ctx context.Context, db *sql.DB) {
	ticker := time.NewTicker(5 * time.Second)
	go func() {
		for {
			select {
			case <-ctx.Done():
				ticker.Stop()
				return
			case <-ticker.C:
				processExpiredOffers(db)
			}
		}
	}()
}

func processExpiredOffers(db *sql.DB) {
	now := time.Now()
	rows, err := db.Query(`
        SELECT a.id, a.journey_id, a.assigned_worker_id, a.role, a.from_location_id, a.to_location_id, j.sample_id, st.id as sample_type_id
        FROM assignments a
        JOIN journeys j ON a.journey_id = j.id
        JOIN samples s ON j.sample_id = s.id
        JOIN sample_types st ON s.sample_type_id = st.id
        WHERE a.status = $1 AND a.offer_expires_at IS NOT NULL AND a.offer_expires_at < $2
    `, models.AssignmentStatusOffered, now)
	if err != nil {
		return
	}
	defer rows.Close()

	type ExpiredOffer struct {
		AssignmentId string
		JourneyId    string
		WorkerId     string
		Role         string
		FromLoc      *string
		ToLoc        *string
		SampleId     string
		SampleTypeId string
	}

	expired := make([]ExpiredOffer, 0)
	for rows.Next() {
		var o ExpiredOffer
		var wId *string
		if err := rows.Scan(&o.AssignmentId, &o.JourneyId, &wId, &o.Role, &o.FromLoc, &o.ToLoc, &o.SampleId, &o.SampleTypeId); err == nil {
			if wId != nil {
				o.WorkerId = *wId
			}
			expired = append(expired, o)
		}
	}

	for _, o := range expired {
		log.Printf("[Worker] Processing expired offer for assignment %s (worker: %s)", o.AssignmentId, o.WorkerId)
		if o.WorkerId != "" {
			_, _ = DeclineAssignment(db, o.AssignmentId, o.WorkerId, "offer_timed_out", now, o.Role)
		}
	}
}
