	}

	if jId.Valid {
		_, _ = db.Exec(`
            UPDATE journeys
            SET status = 'completed', updated_at = NOW()
            WHERE id = $1
        `, jId.String)
		_, _ = db.Exec(`
            UPDATE journey_legs
            SET status = 'completed', completed_at = $1, updated_at = NOW()
            WHERE journey_id = $2
        `, receivedAt, jId.String)
		_, _ = db.Exec(`
            UPDATE capacity_reservations
            SET active = false
            WHERE journey_id = $1
        `, jId.String)
	}

	RecordAudit(db, actorId, actorRole, actorRole, "laboratory_sample_received", "sample", sampleId, true, map[string]interface{}{
