		"operatorId":   operatorId,
	})

	BroadcastEvent(db, "sample_received", "sample", sampleId, map[string]interface{}{
		"laboratoryId": labId,
		"status":       "received",
	})

	return GetSampleLifecycle(db, sampleId)
}

