        SET status = $1, updated_at = NOW()
        WHERE id = $2
    `, status, assignmentId)
	if err != nil {
		return "", err
	}

	if status == "in_transit" {
		_, _ = db.Exec("UPDATE samples SET status = 'in_transit', updated_at = NOW() WHERE id = $1", sampleId)
	}

	RecordAudit(db, workerId, role, role, "assignment_progress_updated", "assignment", assignmentId, true, map[string]interface{}{
