{"summary":"Create CreateRequestModal component","path":"/workspace/frontend/src/components/CreateRequestModal.tsx","file_text":"import React, { useState } from 'react';
import { api, ApiError } from '../api/client';
import { SampleType, Location, Sample } from '../types';

interface CreateRequestModalProps {
  sampleTypes: SampleType[];
  locations: Location[];
  onClose: () => void;
  onSuccess: (sample: Sample) => void;
}

export const CreateRequestModal: React.FC<CreateRequestModalProps> = ({
  sampleTypes,
  locations,
  onClose,
  onSuccess,
}) => {
  const [originType, setOriginType] = useState<'home' | 'clinic' | 'node'>('home');
  const [originAddress, setOriginAddress] = useState('123 MG Road, Bangalore');
  const [originLocationId, setOriginLocationId] = useState<string>('');
  const [lat, setLat] = useState<number>(12.9716);
  const [lng, setLng] = useState<number>(77.5946);
  const [sampleType, setSampleType] = useState<string>(sampleTypes[0]?.code || 'Amber');

  const now = new Date();
  const defaultStart = new Date(now.getTime() + 15 * 60000).toISOString().slice(0, 16);
  const defaultEnd = new Date(now.getTime() + 120 * 60000).toISOString().slice(0, 16);
  const defaultDeadline = new Date(now.getTime() + 360 * 60000).toISOString().slice(0, 16);

  const [windowStart, setWindowStart] = useState<string>(defaultStart);
  const [windowEnd, setWindowEnd] = useState<string>(defaultEnd);
  const [deadline, setDeadline] = useState<string>(defaultDeadline);
  const [notes, setNotes] = useState<string>('');

  const [isLoading, setIsLoading] = useState(false);
  const [validationError, setValidationError] = useState<string | null>(null);

  const handleLocationSelect = (locId: string) => {
    setOriginLocationId(locId);
    const loc = locations.find((l) => l.id === locId);
    if (loc) {
      setLat(loc.latitude);
      setLng(loc.longitude);
      setOriginAddress(loc.name);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setValidationError(null);

    // Form client-side validation
    const startDate = new Date(windowStart);
    const endDate = new Date(windowEnd);
    const deadlineDate = new Date(deadline);

    if (startDate >= endDate) {
      setValidationError('Collection window start must be before collection window end');
      return;
    }

    if (endDate >= deadlineDate) {
      setValidationError('Collection window end must be before delivery deadline');
      return;
    }

    if (originType !== 'home' && !originLocationId) {
      setValidationError('Please select an origin facility');
      return;
    }

    setIsLoading(true);

    try {
      const res = await api.createCollectionRequest({
        originType,
        originAddress,
        originLatitude: lat,
        originLongitude: lng,
        originLocationId: originType !== 'home' ? originLocationId : undefined,
        sampleTypeCode: sampleType,
        collectionWindowStart: startDate.toISOString(),
        collectionWindowEnd: endDate.toISOString(),
        deliveryDeadline: deadlineDate.toISOString(),
        notes,
      });

      onSuccess(res.sample);
    } catch (err: any) {
      if (err instanceof ApiError) {
        setValidationError(err.message || 'Failed to create collection request');
      } else {
        setValidationError(err.message || 'An unexpected error occurred');
      }
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="modal-overlay">
      <div className="modal-content">
        <div className="modal-header">
          <h3 style={{ fontSize: '1.125rem', fontWeight: 600 }}>Create Collection Request</h3>
          <button className="btn btn-secondary btn-sm" onClick={onClose} aria-label="Close">
            ✕
          </button>
        </div>

        <form onSubmit={handleSubmit}>
          {validationError && (
            <div
              style={{
                marginBottom: '1rem',
                padding: '0.75rem',
                backgroundColor: 'var(--danger-light)',
                color: 'var(--danger)',
                borderRadius: '0.375rem',
                fontSize: '0.875rem',
              }}
              role="alert"
            >
              <strong>Validation Error: </strong>
              {validationError}
            </div>
          )}

          <div className="form-group">
            <label className="form-label" htmlFor="req-origin-type">Origin Type</label>
            <select
              id="req-origin-type"
              className="form-select"
              value={originType}
              onChange={(e) => setOriginType(e.target.value as any)}
            >
              <option value="home">Patient Home</option>
              <option value="clinic">Clinic</option>
              <option value="node">Collection Node / Hub</option>
            </select>
          </div>

          {originType !== 'home' ? (
            <div className="form-group">
              <label className="form-label" htmlFor="req-origin-loc">Select Facility</label>
              <select
                id="req-origin-loc"
                className="form-select"
