{"path":"/workspace/frontend/src/components/PresealedSampleModal.tsx","command":"create","summary":"Create PresealedSampleModal component","file_text":"import React, { useState } from 'react';
import { api, ApiError } from '../api/client';
import { SampleType, Location, Sample } from '../types';

interface PresealedSampleModalProps {
  sampleTypes: SampleType[];
  locations: Location[];
  onClose: () => void;
  onSuccess: (sample: Sample) => void;
}

export const PresealedSampleModal: React.FC<PresealedSampleModalProps> = ({
  sampleTypes,
  locations,
  onClose,
  onSuccess,
}) => {
  const [originLocationId, setOriginLocationId] = useState<string>(locations[0]?.id || '');
  const [sampleTypeCode, setSampleTypeCode] = useState<string>(sampleTypes[0]?.code || 'Amber');
  const [containerType, setContainerType] = useState<string>('Standard Tube');
  const [currentTemp, setCurrentTemp] = useState<number>(20);
  const [notes, setNotes] = useState<string>('');

  const now = new Date();
  const defaultDeadline = new Date(now.getTime() + 240 * 60000).toISOString().slice(0, 16);
  const [deadline, setDeadline] = useState<string>(defaultDeadline);

  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!originLocationId) {
      setError('Origin location is required (clinic or network node)');
      return;
    }

    setIsLoading(true);
    setError(null);

    try {
      const res = await api.ingestPresealedSample({
        originLocationId,
        sampleTypeCode,
        containerType,
        currentTemperatureC: currentTemp,
        deliveryDeadline: new Date(deadline).toISOString(),
        notes,
      });

      onSuccess(res.sample);
    } catch (err: any) {
      if (err instanceof ApiError) {
        setError(err.message || 'Failed to ingest presealed sample');
