                marginBottom: '1rem',
                padding: '0.75rem',
                backgroundColor: 'var(--danger-light)',
                color: 'var(--danger)',
                borderRadius: '0.375rem',
                fontSize: '0.875rem',
              }}
            >
              {error}
            </div>
          )}

          <div className="form-group">
            <label className="form-label" htmlFor="pre-loc">Origin Location (Clinic or Node)</label>
