{"path":"/workspace/frontend/src/components/HandoffModal.tsx","file_text":"import React, { useState } from 'react';
import { api, ApiError } from '../api/client';
import { Sample, User, Location, HandoffRecord } from '../types';

interface HandoffModalProps {
  sample: Sample;
  workers: User[];
  locations: Location[];
  existingHandoff?: HandoffRecord | null;
  onClose: () => void;
  onSuccess: (updatedSample: Sample) => void;
}

export const HandoffModal: React.FC<HandoffModalProps> = ({
  sample,
  workers,
  locations,
  existingHandoff,
  onClose,
  onSuccess,
}) => {
  const [receiverUserId, setReceiverUserId] = useState<string>(workers[0]?.id || '');
  const [locationId, setLocationId] = useState<string>(locations[0]?.id || '');
  const [containerType, setContainerType] = useState('Standard Insulated Box');
  const [temperatureC, setTemperatureC] = useState<number>(sample.requiresCooled ? 4.0 : 20.0);

  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleInitiate = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError(null);

    try {
      await api.initiateHandoff({
        sampleId: sample.id,
        receiverUserId,
        locationId,
        containerType,
        temperatureC,
      });

      // Fetch refreshed sample state
      const refreshed = await api.getSampleState(sample.id);
      onSuccess(refreshed.sample);
    } catch (err: any) {
      if (err instanceof ApiError) {
        setError(err.message || 'Failed to initiate handoff');
      } else {
        setError(err.message || 'Network error');
      }
    } finally {
      setIsLoading(false);
    }
  };

  const handleConfirm = async (roleInHandoff: 'sender' | 'receiver') => {
    if (!existingHandoff) return;
    setIsLoading(true);
    setError(null);

    try {
      const res = await api.confirmHandoff({
        handoffId: existingHandoff.id,
        roleInHandoff,
        observedContainerType: containerType,
        observedTemperatureC: temperatureC,
      });

      onSuccess(res.sample);
    } catch (err: any) {
      if (err instanceof ApiError) {
        setError(err.message || 'Failed to confirm handoff');
      } else {
        setError(err.message || 'Network error');
      }
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="modal-overlay">
      <div className="modal-content">
        <div className="modal-header">
          <h3 style={{ fontSize: '1.125rem', fontWeight: 600 }}>Custody Handoff</h3>
          <button className="btn btn-secondary btn-sm" onClick={onClose} aria-label="Close">
            ✕
          </button>
        </div>

        {error && (
          <div
            style={{
              marginBottom: '1rem',
              padding: '0.75rem',
              backgroundColor: 'var(--danger-light)',
              color: 'var(--danger)',
              borderRadius: '0.375rem',
              fontSize: '0.875rem',
            }}
          >
            {error}
          </div>
        )}

        {existingHandoff ? (
          <div>
            <p style={{ fontSize: '0.875rem', marginBottom: '1rem' }}>
              Handoff for sample <strong>{sample.trackingNumber}</strong> is currently pending confirmation:
            </p>

            <div style={{ backgroundColor: 'var(--gray-50)', padding: '1rem', borderRadius: '0.375rem', marginBottom: '1rem', border: '1px solid var(--gray-200)' }}>
              <div><strong>Sender:</strong> {existingHandoff.senderName || existingHandoff.senderUserId} {existingHandoff.senderConfirmed ? '✅ Confirmed' : '⏳ Pending'}</div>
              <div style={{ marginTop: '0.5rem' }}><strong>Receiver:</strong> {existingHandoff.receiverName || existingHandoff.receiverUserId} {existingHandoff.receiverConfirmed ? '✅ Confirmed' : '⏳ Pending'}</div>
            </div>

            <div className="grid grid-cols-2" style={{ marginBottom: '1rem' }}>
              <div className="form-group">
                <label className="form-label" htmlFor="handoff-conf-container">Observed Container</label>
                <input
                  id="handoff-conf-container"
                  type="text"
                  className="form-input"
                  value={containerType}
                  onChange={(e) => setContainerType(e.target.value)}
                />
              </div>
              <div className="form-group">
                <label className="form-label" htmlFor="handoff-conf-temp">Observed Temp (°C)</label>
                <input
                  id="handoff-conf-temp"
                  type="number"
                  step="0.1"
                  className="form-input"
                  value={temperatureC}
                  onChange={(e) => setTemperatureC(parseFloat(e.target.value))}
                />
              </div>
            </div>

            <div style={{ display: 'flex', gap: '0.75rem', justifyContent: 'flex-end' }}>
              {!existingHandoff.senderConfirmed && (
                <button
                  type="button"
                  className="btn btn-primary"
                  onClick={() => handleConfirm('sender')}
                  disabled={isLoading}
                  aria-label="Confirm As Sender"
                >
                  Confirm as Sender
                </button>
              )}
              {!existingHandoff.receiverConfirmed && (
                <button
                  type="button"
                  className="btn btn-success"
                  onClick={() => handleConfirm('receiver')}
                  disabled={isLoading}
                  aria-label="Confirm As Receiver"
                >
                  Confirm as Receiver (Take Custody)
                </button>
              )}
            </div>
          </div>
        ) : (
          <form onSubmit={handleInitiate}>
            <p style={{ fontSize: '0.875rem', color: 'var(--gray-600)', marginBottom: '1rem' }}>
              Initiate custody transfer for sample <strong>{sample.trackingNumber}</strong>. Both you and the recipient must confirm.
            </p>

            <div className="form-group">
              <label className="form-label" htmlFor="handoff-receiver">Transfer To Worker</label>
              <select
                id="handoff-receiver"
                className="form-select"
                value={receiverUserId}
                onChange={(e) => setReceiverUserId(e.target.value)}
                required
              >
                {workers.map((w) => (
                  <option key={w.id} value={w.id}>
                    {w.fullName || w.username} ({w.activeRole || 'No active role'})
                  </option>
                ))}
              </select>
            </div>

            <div className="form-group">
              <label className="form-label" htmlFor="handoff-location">Transfer Location</label>
              <select
                id="handoff-location"
                className="form-select"
                value={locationId}
                onChange={(e) => setLocationId(e.target.value)}
              >
                {locations.map((loc) => (
                  <option key={loc.id} value={loc.id}>
                    {loc.name} ({loc.code})
                  </option>
                ))}
              </select>
            </div>

            <div className="grid grid-cols-2">
              <div className="form-group">
                <label className="form-label" htmlFor="handoff-init-container">Container Type</label>
                <input
                  id="handoff-init-container"
                  type="text"
                  className="form-input"
                  value={containerType}
                  onChange={(e) => setContainerType(e.target.value)}
                  required
                />
              </div>
              <div className="form-group">
                <label className="form-label" htmlFor="handoff-init-temp">Temperature (°C)</label>
                <input
                  id="handoff-init-temp"
                  type="number"
                  step="0.1"
                  className="form-input"
                  value={temperatureC}
                  onChange={(e) => setTemperatureC(parseFloat(e.target.value))}
                  required
                />
              </div>
            </div>

            <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '0.75rem', marginTop: '1rem' }}>
              <button type="button" className="btn btn-secondary" onClick={onClose}>
                Cancel
              </button>
              <button
                type="submit"
                className="btn btn-primary"
                disabled={isLoading}
                aria-label="Initiate Handoff"
              >
                {isLoading ? 'Initiating...' : 'Initiate Handoff'}
              </button>
            </div>
          </form>
        )}
      </div>
    </div>
  );
};
