{"command":"create","summary":"Create SampleDetailModal component","path":"/workspace/frontend/src/components/SampleDetailModal.tsx","file_text":"import React, { useEffect, useState } from 'react';
import { api } from '../api/client';
import { Sample, StatusEvent, HandoffRecord, User, Location } from '../types';
import { Timeline } from './Timeline';
import { HandlingCheckpointModal } from './HandlingCheckpointModal';
import { HandoffModal } from './HandoffModal';

interface SampleDetailModalProps {
  sampleId: string;
  workers: User[];
  locations: Location[];
  currentUserId?: string;
  onClose: () => void;
}

export const SampleDetailModal: React.FC<SampleDetailModalProps> = ({
  sampleId,
  workers,
  locations,
  currentUserId,
  onClose,
}) => {
  const [sample, setSample] = useState<Sample | null>(null);
  const [timeline, setTimeline] = useState<StatusEvent[]>([]);
  const [handoffs, setHandoffs] = useState<HandoffRecord[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [showCheckpointModal, setShowCheckpointModal] = useState(false);
  const [showHandoffModal, setShowHandoffModal] = useState(false);

  const loadData = async () => {
    setIsLoading(true);
    setError(null);
    try {
      const res = await api.getSampleLifecycle(sampleId);
      setSample(res.sample);
      setTimeline(res.timeline || []);
      setHandoffs(res.handoffs || []);
    } catch (err: any) {
      setError(err.message || 'Failed to load sample details');
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, [sampleId]);

  if (isLoading) {
    return (
      <div className="modal-overlay">
        <div className="modal-content">
          <p>Loading sample details...</p>
        </div>
      </div>
    );
  }

  if (error || !sample) {
    return (
      <div className="modal-overlay">
        <div className="modal-content">
          <div className="modal-header">
            <h3>Error</h3>
            <button className="btn btn-secondary btn-sm" onClick={onClose}>✕</button>
          </div>
          <p style={{ color: 'var(--danger)' }}>{error || 'Sample not found'}</p>
        </div>
      </div>
    );
  }

  const isCurrentHolder = currentUserId && sample.currentHolderUserId === currentUserId;
  const pendingHandoff = handoffs.find((h) => h.status === 'initiated');

  const formatDateTime = (ts?: string) => {
    if (!ts) return 'N/A';
    try {
      return new Date(ts).toLocaleString();
    } catch {
      return ts;
    }
  };

  return (
    <>
      <div className="modal-overlay">
        <div className="modal-content" style={{ maxWidth: '750px' }}>
          <div className="modal-header">
            <div>
              <h3 style={{ fontSize: '1.25rem', fontWeight: 700 }}>
                Sample: {sample.trackingNumber}
              </h3>
              <span style={{ fontSize: '0.8125rem', color: 'var(--gray-500)' }}>
                ID: {sample.id}
              </span>
            </div>
            <button className="btn btn-secondary btn-sm" onClick={onClose} aria-label="Close">
              ✕
            </button>
          </div>

          {/* Exception Alert */}
          {(sample.isException || sample.status === 'exception' || sample.exceptionReason) && (
            <div
              style={{
                backgroundColor: 'var(--danger-light)',
                border: '1px solid var(--danger)',
                color: 'var(--danger)',
                padding: '0.75rem 1rem',
                borderRadius: '0.375rem',
                marginBottom: '1rem',
                display: 'flex',
                alignItems: 'center',
                gap: '0.5rem',
              }}
              role="alert"
            >
              <span style={{ fontSize: '1.25rem' }}>⚠️</span>
              <div>
                <strong>Sample Exception Flagged:</strong>{' '}
                {sample.exceptionReason || 'Irregularity observed or constraint violated'}
              </div>
            </div>
          )}

          {/* Key Details Grid */}
          <div className="grid grid-cols-3" style={{ marginBottom: '1.25rem' }}>
            <div style={{ backgroundColor: 'var(--gray-50)', padding: '0.75rem', borderRadius: '0.375rem', border: '1px solid var(--gray-200)' }}>
              <div style={{ fontSize: '0.75rem', color: 'var(--gray-500)', textTransform: 'uppercase' }}>Status</div>
              <div style={{ fontWeight: 600, fontSize: '0.9375rem', marginTop: '0.25rem' }}>
                <span className={`badge ${sample.status === 'received' ? 'badge-success' : sample.status === 'exception' || sample.status === 'expired' ? 'badge-danger' : 'badge-info'}`}>
                  {sample.status}
                </span>
              </div>
            </div>

            <div style={{ backgroundColor: 'var(--gray-50)', padding: '0.75rem', borderRadius: '0.375rem', border: '1px solid var(--gray-200)' }}>
              <div style={{ fontSize: '0.75rem', color: 'var(--gray-500)', textTransform: 'uppercase' }}>Current Custodian</div>
              <div style={{ fontWeight: 600, fontSize: '0.9375rem', marginTop: '0.25rem', color: 'var(--gray-800)' }}>
                {sample.currentHolderName || sample.currentHolderUserId || 'None / Not sealed'}
              </div>
            </div>

            <div style={{ backgroundColor: 'var(--gray-50)', padding: '0.75rem', borderRadius: '0.375rem', border: '1px solid var(--gray-200)' }}>
              <div style={{ fontSize: '0.75rem', color: 'var(--gray-500)', textTransform: 'uppercase' }}>Location Freshness</div>
              <div style={{ fontWeight: 600, fontSize: '0.9375rem', marginTop: '0.25rem' }}>
                {sample.isLocationStale ? (
                  <span className="badge badge-warning">⚠️ Stale Location</span>
                ) : (
                  <span className="badge badge-success">✓ Fresh</span>
                )}
                {sample.locationUpdatedAt && (
                  <div style={{ fontSize: '0.7rem', color: 'var(--gray-500)', marginTop: '2px' }}>
                    Updated {formatDateTime(sample.locationUpdatedAt)}
                  </div>
                )}
              </div>
            </div>
          </div>

          <div className="grid grid-cols-2" style={{ marginBottom: '1.25rem' }}>
            <div>
              <h4 style={{ fontSize: '0.875rem', fontWeight: 600, color: 'var(--gray-700)', marginBottom: '0.5rem' }}>
                Sample Properties
              </h4>
              <ul style={{ fontSize: '0.8125rem', listStyle: 'none', color: 'var(--gray-600)' }}>
                <li style={{ marginBottom: '0.25rem' }}><strong>Type:</strong> {sample.sampleTypeCode}</li>
                <li style={{ marginBottom: '0.25rem' }}><strong>Origin:</strong> {sample.originType} ({sample.originAddress || `${sample.originLatitude}, ${sample.originLongitude}`})</li>
                <li style={{ marginBottom: '0.25rem' }}><strong>Requires Cooled:</strong> {sample.requiresCooled ? 'Yes (2°C - 8°C)' : 'No'}</li>
                <li style={{ marginBottom: '0.25rem' }}><strong>Qualified Collector:</strong> {sample.requiresQualifiedCollector ? 'Required' : 'Standard'}</li>
                {sample.sealedAt && <li style={{ marginBottom: '0.25rem' }}><strong>Sealed At:</strong> {formatDateTime(sample.sealedAt)}</li>}
              </ul>
            </div>

            <div>
              <h4 style={{ fontSize: '0.875rem', fontWeight: 600, color: 'var(--gray-700)', marginBottom: '0.5rem' }}>
                Time Constraints
              </h4>
              <ul style={{ fontSize: '0.8125rem', listStyle: 'none', color: 'var(--gray-600)' }}>
                <li style={{ marginBottom: '0.25rem' }}><strong>Window Start:</strong> {formatDateTime(sample.collectionWindowStart)}</li>
                <li style={{ marginBottom: '0.25rem' }}><strong>Window End:</strong> {formatDateTime(sample.collectionWindowEnd)}</li>
                <li style={{ marginBottom: '0.25rem' }}><strong>Delivery Deadline:</strong> <span style={{ color: 'var(--danger)', fontWeight: 600 }}>{formatDateTime(sample.deliveryDeadline)}</span></li>
                <li style={{ marginBottom: '0.25rem' }}><strong>Current Location:</strong> {sample.currentLatitude ? `${sample.currentLatitude.toFixed(4)}, ${sample.currentLongitude?.toFixed(4)}` : 'N/A'}</li>
              </ul>
            </div>
          </div>

          {/* Custody Actions */}
          <div style={{ display: 'flex', gap: '0.75rem', padding: '0.75rem', backgroundColor: 'var(--gray-100)', borderRadius: '0.375rem', marginBottom: '1.25rem' }}>
            <button
              className="btn btn-secondary btn-sm"
              onClick={() => setShowCheckpointModal(true)}
              aria-label="Record Handling Checkpoint"
            >
              🌡️ Record Handling Checkpoint
            </button>

            <button
              className="btn btn-primary btn-sm"
              onClick={() => setShowHandoffModal(true)}
              aria-label="Manage Handoff"
            >
              🤝 {pendingHandoff ? 'Confirm Custody Handoff' : 'Initiate Custody Handoff'}
            </button>
          </div>

          {/* Status Timeline */}
          <div>
            <h4 style={{ fontSize: '1rem', fontWeight: 600, marginBottom: '0.5rem' }}>
              Status History & Chain of Custody
            </h4>
            <Timeline events={timeline} />
          </div>
        </div>
      </div>

      {showCheckpointModal && (
        <HandlingCheckpointModal
          sample={sample}
          onClose={() => setShowCheckpointModal(false)}
          onSuccess={(updated) => {
            setSample(updated);
            setShowCheckpointModal(false);
            loadData();
          }}
        />
      )}

      {showHandoffModal && (
        <HandoffModal
          sample={sample}
          workers={workers}
          locations={locations}
          existingHandoff={pendingHandoff}
          onClose={() => setShowHandoffModal(false)}
          onSuccess={(updated) => {
            setSample(updated);
            setShowHandoffModal(false);
            loadData();
          }}
        />
      )}
    </>
  );
};
"}

{"command":"create","summary":"Create LocationRecorder component","path":"/workspace/frontend/src/components/LocationRecorder.tsx","file_text":"import React, { useState } from 'react';
import { api, ApiError } from '../api/client';

interface LocationRecorderProps {
  onLocationRecorded?: () => void;
}

export const LocationRecorder: React.FC<LocationRecorderProps> = ({ onLocationRecorded }) => {
  const [lat, setLat] = useState<number>(12.9716);
  const [lng, setLng] = useState<number>(77.5946);
  const [isLoading, setIsLoading] = useState(false);
  const [message, setMessage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const handleRecord = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError(null);
    setMessage(null);

    try {
      await api.recordWorkerLocation(lat, lng);
      setMessage(`Location recorded: ${lat.toFixed(4)}, ${lng.toFixed(4)}`);
      if (onLocationRecorded) onLocationRecorded();
    } catch (err: any) {
      if (err instanceof ApiError) {
        setError(err.message || 'Failed to record location');
      } else {
        setError(err.message || 'Network error');
      }
    } finally {
      setIsLoading(false);
    }
  };

  const handleUseBrowserLocation = () => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (pos) => {
          setLat(pos.coords.latitude);
          setLng(pos.coords.longitude);
        },
        () => {
          // Default fallback
          setLat(12.975);
          setLng(77.605);
        }
      );
    }
  };

  return (
    <div className="card" style={{ marginBottom: '1rem' }}>
      <div className="card-header">
        <h3 style={{ fontSize: '0.9375rem', fontWeight: 600 }}>📍 Record Current Location</h3>
        <button
          type="button"
          className="btn btn-secondary btn-sm"
          onClick={handleUseBrowserLocation}
          aria-label="Use GPS"
        >
          Use Device GPS
        </button>
      </div>

      <form onSubmit={handleRecord} style={{ display: 'flex', alignItems: 'flex-end', gap: '0.75rem', flexWrap: 'wrap' }}>
        <div style={{ flex: 1, minWidth: '140px' }}>
          <label className="form-label" htmlFor="loc-lat">Latitude</label>
          <input
            id="loc-lat"
            type="number"
            step="any"
            className="form-input"
            value={lat}
            onChange={(e) => setLat(parseFloat(e.target.value))}
            required
          />
        </div>

        <div style={{ flex: 1, minWidth: '140px' }}>
          <label className="form-label" htmlFor="loc-lng">Longitude</label>
          <input
            id="loc-lng"
            type="number"
            step="any"
            className="form-input"
            value={lng}
            onChange={(e) => setLng(parseFloat(e.target.value))}
            required
          />
        </div>

        <button
          type="submit"
          className="btn btn-primary"
          disabled={isLoading}
          aria-label="Record Location"
        >
          {isLoading ? 'Saving...' : 'Record Location'}
        </button>
      </form>

      {message && (
        <div style={{ marginTop: '0.5rem', fontSize: '0.8125rem', color: 'var(--success)' }}>
          ✅ {message}
        </div>
      )}

      {error && (
        <div style={{ marginTop: '0.5rem', fontSize: '0.8125rem', color: 'var(--danger)' }}>
          ❌ {error}
        </div>
      )}
    </div>
  );
};
"}

{"file_text":"import React, { useState } from 'react';
import { api, ApiError } from '../api/client';
import { Location, NetworkConnection, User } from '../types';

interface CapacityManagerProps {
  locations: Location[];
  connections: NetworkConnection[];
  currentUser: User;
  onRefresh: () => void;
}

export const CapacityManager: React.FC<CapacityManagerProps> = ({
  locations,
  connections,
  currentUser,
  onRefresh,
}) => {
  const [targetType, setTargetType] = useState<'location' | 'connection'>('location');
  const [targetId, setTargetId] = useState<string>(
    currentUser.assignedLocationId || locations[0]?.id || ''
  );
  const [regularCap, setRegularCap] = useState<number>(50);
  const [cooledCap, setCooledCap] = useState<number>(20);

  const [isLoading, setIsLoading] = useState(false);
  const [message, setMessage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  // Filter locations if node handler or lab operator is assigned to a specific node
  const isAssigned = !!currentUser.assignedLocationId;
  const filteredLocations = isAssigned
    ? locations.filter((l) => l.id === currentUser.assignedLocationId)
    : locations;

  const handleTargetChange = (id: string) => {
    setTargetId(id);
    if (targetType === 'location') {
      const loc = locations.find((l) => l.id === id);
      if (loc) {
        setRegularCap(loc.regularCapacity);
        setCooledCap(loc.cooledCapacity);
      }
    } else {
      const conn = connections.find((c) => c.id === id);
      if (conn) {
        setRegularCap(conn.regularCapacity);
        setCooledCap(conn.cooledCapacity);
      }
    }
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError(null);
    setMessage(null);

    try {
      await api.configureCapacity({
        targetType,
        targetId,
        regularCapacity: Number(regularCap),
        cooledCapacity: Number(cooledCap),
      });

      setMessage('Capacity updated successfully');
      onRefresh();
    } catch (err: any) {
      if (err instanceof ApiError) {
        setError(err.message || 'Failed to update capacity');
      } else {
        setError(err.message || 'Network error');
      }
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="card">
      <div className="card-header">
        <h2 className="card-title">Capacity Management</h2>
        <span className="badge badge-info">Regular & Cooled Capacity Pools</span>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1.5rem' }}>
        <form onSubmit={handleSave}>
          <div className="form-group">
            <label className="form-label" htmlFor="cap-target-type">Target Type</label>
            <select
              id="cap-target-type"
              className="form-select"
              value={targetType}
              onChange={(e) => {
                const t = e.target.value as 'location' | 'connection';
                setTargetType(t);
                if (t === 'location') {
                  setTargetId(filteredLocations[0]?.id || '');
                } else {
                  setTargetId(connections[0]?.id || '');
                }
              }}
              disabled={isAssigned}
            >
              <option value="location">Location / Facility</option>
              {!isAssigned && <option value="connection">Transport Connection</option>}
            </select>
          </div>

          <div className="form-group">
            <label className="form-label" htmlFor="cap-target">Select Target</label>
            <select
              id="cap-target"
              className="form-select"
              value={targetId}
              onChange={(e) => handleTargetChange(e.target.value)}
              required
            >
              {targetType === 'location' ? (
                filteredLocations.map((l) => (
                  <option key={l.id} value={l.id}>
                    {l.name} ({l.code}) - {l.isLaboratory ? 'Lab' : 'Node'}
                  </option>
                ))
              ) : (
                connections.map((c) => (
                  <option key={c.id} value={c.id}>
                    Connection: {c.fromLocationId} → {c.toLocationId}
                  </option>
                ))
              )}
            </select>
          </div>

          <div className="grid grid-cols-2">
            <div className="form-group">
              <label className="form-label" htmlFor="cap-regular">Configured Regular Capacity</label>
              <input
                id="cap-regular"
                type="number"
                min="0"
                className="form-input"
                value={regularCap}
                onChange={(e) => setRegularCap(parseInt(e.target.value, 10))}
                required
              />
            </div>

            <div className="form-group">
              <label className="form-label" htmlFor="cap-cooled">Configured Cooled Capacity</label>
              <input
                id="cap-cooled"
                type="number"
                min="0"
                className="form-input"
                value={cooledCap}
                onChange={(e) => setCooledCap(parseInt(e.target.value, 10))}
                required
              />
            </div>
          </div>

          <button
            type="submit"
            className="btn btn-primary"
            disabled={isLoading}
            aria-label="Save Capacity"
          >
            {isLoading ? 'Saving...' : 'Update Capacity'}
          </button>

          {message && (
            <div style={{ marginTop: '0.75rem', padding: '0.5rem', backgroundColor: 'var(--success-light)', color: 'var(--success)', borderRadius: '0.375rem', fontSize: '0.875rem' }}>
              ✓ {message}
            </div>
          )}

          {error && (
            <div style={{ marginTop: '0.75rem', padding: '0.5rem', backgroundColor: 'var(--danger-light)', color: 'var(--danger)', borderRadius: '0.375rem', fontSize: '0.875rem' }}>
              ❌ {error}
            </div>
          )}
        </form>

        {/* Capacity Overview Table */}
        <div className="table-container">
          <h4 style={{ fontSize: '0.875rem', fontWeight: 600, marginBottom: '0.5rem' }}>Current Capacity Status</h4>
          <table className="table">
            <thead>
              <tr>
                <th>Location</th>
                <th>Regular (Avail/Tot)</th>
                <th>Cooled (Avail/Tot)</th>
              </tr>
            </thead>
            <tbody>
              {filteredLocations.map((loc) => {
                const regAvail = loc.regularCapacity - (loc.reservedRegularCapacity || 0);
                const coolAvail = loc.cooledCapacity - (loc.reservedCooledCapacity || 0);
                return (
                  <tr key={loc.id}>
                    <td>
                      <div style={{ fontWeight: 600 }}>{loc.name}</div>
                      <div style={{ fontSize: '0.75rem', color: 'var(--gray-500)' }}>{loc.code}</div>
                    </td>
                    <td>
                      <span className={`badge ${regAvail <= 0 ? 'badge-danger' : 'badge-success'}`}>
                        {regAvail} / {loc.regularCapacity}
                      </span>
                    </td>
                    <td>
                      <span className={`badge ${coolAvail <= 0 ? 'badge-danger' : 'badge-info'}`}>
                        {coolAvail} / {loc.cooledCapacity}
                      </span>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};
