{"command":"create","summary":"Create DispatcherDashboard component","path":"/workspace/frontend/src/components/DispatcherDashboard.tsx","file_text":"import React, { useState, useEffect } from 'react';
import { api, ApiError } from '../api/client';
import { OperationsState, Sample, Journey, Location, User, NetworkConnection, SampleType } from '../types';
import { MapComponent } from './Map';
import { SampleDetailModal } from './SampleDetailModal';

interface DispatcherDashboardProps {
  locations: Location[];
  connections: NetworkConnection[];
  sampleTypes: SampleType[];
  workers: User[];
  onRefreshAll: () => void;
}

export const DispatcherDashboard: React.FC<DispatcherDashboardProps> = ({
  locations,
  connections,
  sampleTypes,
  workers,
  onRefreshAll,
}) => {
  const [opsState, setOpsState] = useState<OperationsState | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Modals & detail view
  const [selectedSampleId, setSelectedSampleId] = useState<string | null>(null);
  const [selectedJourney, setSelectedJourney] = useState<Journey | null>(null);

  // Replanning state
  const [disruptionTargetType, setDisruptionTargetType] = useState<'worker' | 'node' | 'connection' | 'laboratory'>('worker');
  const [disruptionTargetId, setDisruptionTargetId] = useState<string>('');
  const [disruptionReason, setDisruptionReason] = useState('Vehicle breakdown / network delay');

  const [splitLocationId, setSplitLocationId] = useState<string>('');
  const [mergeLocationId, setMergeLocationId] = useState<string>('');
  const [selectedJourneysForMerge, setSelectedJourneysForMerge] = useState<string[]>([]);

  const loadOperations = async () => {
    setIsLoading(true);
    setError(null);
    try {
      const res = await api.getOperationsState();
      setOpsState(res);
      if (locations.length > 0 && !splitLocationId) {
        setSplitLocationId(locations[0].id);
        setMergeLocationId(locations[0].id);
      }
    } catch (err: any) {
      if (err instanceof ApiError) {
        setError(err.message || 'Failed to load operations state');
      } else {
        setError(err.message || 'Network error');
      }
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    loadOperations();
    const interval = setInterval(loadOperations, 15000); // 15s auto-poll
    return () => clearInterval(interval);
  }, []);

  const handleReroute = async (journey: Journey) => {
    const reason = prompt('Enter rerouting reason:', 'Network disruption / alternate route');
    if (!reason) return;
    try {
      await api.rerouteJourney({
        journeyId: journey.id,
        expectedVersion: journey.planVersion,
        reason,
      });
      alert('Journey successfully rerouted');
      loadOperations();
      onRefreshAll();
    } catch (err: any) {
      alert(err.message || 'Failed to reroute journey');
    }
  };

  const handleCancel = async (journey: Journey) => {
    const reason = prompt('Enter cancellation reason:', 'Requester cancellation');
    if (!reason) return;
    try {
      await api.cancelJourney({
        journeyId: journey.id,
        reason,
      });
      alert('Journey cancelled');
      loadOperations();
      onRefreshAll();
    } catch (err: any) {
      alert(err.message || 'Failed to cancel journey');
    }
  };

  const handleSplit = async (journey: Journey) => {
    try {
      await api.splitJourney({
        journeyId: journey.id,
        expectedVersion: journey.planVersion,
        splitLocationId: splitLocationId || locations[0].id,
      });
      alert('Journey split successfully');
      loadOperations();
      onRefreshAll();
    } catch (err: any) {
      alert(err.message || 'Failed to split journey');
    }
  };

  const handleMerge = async () => {
    if (selectedJourneysForMerge.length < 2) {
      alert('Please select at least 2 journeys to combine into a batch');
      return;
    }
    try {
      await api.mergeJourneys({
        journeyIds: selectedJourneysForMerge,
        mergeLocationId: mergeLocationId || locations[0].id,
      });
      alert('Journeys merged into batch successfully');
      setSelectedJourneysForMerge([]);
      loadOperations();
      onRefreshAll();
    } catch (err: any) {
      alert(err.message || 'Failed to merge journeys');
    }
  };

  const handleReportDisruption = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!disruptionTargetId) {
      alert('Please select a target for the disruption');
      return;
    }
    try {
      const res = await api.reportDisruption({
        targetType: disruptionTargetType,
        targetId: disruptionTargetId,
        reason: disruptionReason,
      });
      alert(`Disruption processed: ${res.affectedJourneys} affected, ${res.reroutedCount} rerouted, ${res.exceptionCount} exceptions flagged.`);
      loadOperations();
      onRefreshAll();
    } catch (err: any) {
      alert(err.message || 'Failed to report disruption');
    }
  };

  const samples = opsState?.samples || [];
  const journeys = opsState?.journeys || [];
  const opWorkers = opsState?.workers || workers;

  const staleSamplesCount = samples.filter((s) => s.isLocationStale).length;
  const exceptionSamplesCount = samples.filter((s) => s.isException || s.status === 'exception').length;

  return (
    <div>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.25rem' }}>
        <div>
          <h2 style={{ fontSize: '1.5rem', fontWeight: 700, color: 'var(--gray-900)' }}>
            Dispatcher Control Center
          </h2>
          <p style={{ fontSize: '0.875rem', color: 'var(--gray-500)' }}>
            Live tracking of journeys, samples, worker custody, capacity and route replanning
          </p>
        </div>

        <button className="btn btn-secondary" onClick={loadOperations} aria-label="Refresh Operations">
          🔄 Refresh Operations
        </button>
      </div>

      {/* Overview Stat Cards */}
      <div className="grid grid-cols-4" style={{ marginBottom: '1.5rem' }}>
        <div className="card" style={{ marginBottom: 0 }}>
          <div style={{ fontSize: '0.75rem', color: 'var(--gray-500)', textTransform: 'uppercase' }}>Active Samples</div>
          <div style={{ fontSize: '1.75rem', fontWeight: 700, color: 'var(--primary)' }}>
            {samples.length}
          </div>
        </div>

        <div className="card" style={{ marginBottom: 0 }}>
          <div style={{ fontSize: '0.75rem', color: 'var(--gray-500)', textTransform: 'uppercase' }}>Active Journeys</div>
          <div style={{ fontSize: '1.75rem', fontWeight: 700, color: 'var(--gray-800)' }}>
            {journeys.length}
          </div>
        </div>

        <div className="card" style={{ marginBottom: 0 }}>
          <div style={{ fontSize: '0.75rem', color: 'var(--gray-500)', textTransform: 'uppercase' }}>Exceptions Flagged</div>
          <div style={{ fontSize: '1.75rem', fontWeight: 700, color: exceptionSamplesCount > 0 ? 'var(--danger)' : 'var(--success)' }}>
            {exceptionSamplesCount}
          </div>
        </div>

        <div className="card" style={{ marginBottom: 0 }}>
          <div style={{ fontSize: '0.75rem', color: 'var(--gray-500)', textTransform: 'uppercase' }}>Stale Locations</div>
          <div style={{ fontSize: '1.75rem', fontWeight: 700, color: staleSamplesCount > 0 ? 'var(--warning)' : 'var(--success)' }}>
            {staleSamplesCount}
          </div>
        </div>
      </div>

      {/* Live Map */}
      <div className="card" style={{ marginBottom: '1.5rem' }}>
        <div className="card-header">
          <h3 className="card-title">Live Network Map</h3>
          <span style={{ fontSize: '0.8125rem', color: 'var(--gray-500)' }}>
            🔵 Samples | 🚗 Couriers | 🔬 Laboratories | 🏢 Hubs
          </span>
        </div>
        <MapComponent
          locations={locations}
          samples={samples}
          workers={opWorkers}
          height="450px"
        />
      </div>

      {/* Live Samples Table */}
      <div className="card">
        <div className="card-header">
          <h3 className="card-title">Active Samples & Custody Tracking</h3>
        </div>

        <div className="table-container">
          <table className="table">
            <thead>
              <tr>
                <th>Tracking Number</th>
                <th>Type</th>
                <th>Status</th>
                <th>Current Custodian</th>
                <th>Location & Freshness</th>
                <th>Delivery Deadline</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {samples.length === 0 ? (
                <tr>
                  <td colSpan={7} style={{ textAlign: 'center', padding: '1.5rem', color: 'var(--gray-500)' }}>
                    No active samples in network.
                  </td>
                </tr>
              ) : (
                samples.map((s) => (
                  <tr key={s.id}>
                    <td>
                      <button
                        style={{
                          background: 'none',
                          border: 'none',
                          fontWeight: 700,
                          color: 'var(--primary)',
                          cursor: 'pointer',
                          padding: 0,
                        }}
                        onClick={() => setSelectedSampleId(s.id)}
                      >
                        {s.trackingNumber}
                      </button>
                    </td>

                    <td>
                      <span className="badge badge-gray">{s.sampleTypeCode}</span>
                      {s.requiresCooled && <span className="badge badge-info" style={{ marginLeft: '4px' }}>❄️</span>}
                    </td>

                    <td>
                      <span
                        className={`badge ${
                          s.status === 'received'
                            ? 'badge-success'
                            : s.status === 'exception' || s.status === 'expired'
                            ? 'badge-danger'
                            : 'badge-info'
                        }`}
                      >
                        {s.status}
                      </span>
                      {s.isException && (
                        <div style={{ fontSize: '0.7rem', color: 'var(--danger)', fontWeight: 600 }}>
                          ⚠️ {s.exceptionReason || 'Exception'}
                        </div>
                      )}
                    </td>

                    <td>
                      <strong>{s.currentHolderName || s.currentHolderUserId || 'Unassigned'}</strong>
                    </td>

                    <td>
                      {s.isLocationStale ? (
                        <span className="badge badge-warning">⚠️ Stale</span>
                      ) : (
                        <span className="badge badge-success">✓ Fresh</span>
                      )}
                      <div style={{ fontSize: '0.75rem', color: 'var(--gray-500)' }}>
                        {s.currentLatitude ? `${s.currentLatitude.toFixed(3)}, ${s.currentLongitude?.toFixed(3)}` : 'N/A'}
                      </div>
                    </td>

                    <td>
                      <span style={{ fontSize: '0.8125rem' }}>
                        {new Date(s.deliveryDeadline).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                      </span>
                    </td>

                    <td>
                      <button
                        className="btn btn-secondary btn-sm"
                        onClick={() => setSelectedSampleId(s.id)}
                      >
                        View Lifecycle
                      </button>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Journeys & Replanning */}
      <div className="grid grid-cols-2">
        <div className="card">
          <div className="card-header">
            <h3 className="card-title">Active Journeys & Legs</h3>
          </div>

          {journeys.length === 0 ? (
            <p style={{ color: 'var(--gray-500)', fontSize: '0.875rem' }}>No active journeys.</p>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
              {journeys.map((j) => (
                <div
                  key={j.id}
                  style={{
                    border: '1px solid var(--gray-200)',
                    borderRadius: '0.375rem',
                    padding: '1rem',
                    backgroundColor: 'var(--gray-50)',
                  }}
                >
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '0.5rem' }}>
                    <div>
                      <strong>Journey: {j.id.slice(0, 8)}...</strong>
                      <span className="badge badge-info" style={{ marginLeft: '0.5rem' }}>
                        v{j.planVersion}
                      </span>
                      {j.isBatch && <span className="badge badge-warning" style={{ marginLeft: '0.25rem' }}>Batch</span>}
                    </div>
                    <span className="badge badge-gray">{j.status}</span>
                  </div>

                  {/* Legs list */}
                  <div style={{ fontSize: '0.8125rem', marginBottom: '0.75rem' }}>
                    <div style={{ fontWeight: 600, color: 'var(--gray-700)', marginBottom: '0.25rem' }}>Legs:</div>
                    {j.legs?.map((leg) => (
                      <div key={leg.id} style={{ display: 'flex', justifyContent: 'space-between', padding: '2px 0' }}>
                        <span>
                          {leg.legSequence}. {leg.legType}: {leg.assignedUserName || 'Unassigned'}
                        </span>
                        <span className={`badge ${leg.status === 'completed' ? 'badge-success' : 'badge-gray'}`}>
                          {leg.status}
                        </span>
                      </div>
                    ))}
                  </div>

                  {/* Replanning action buttons */}
                  <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap', borderTop: '1px solid var(--gray-200)', paddingTop: '0.5rem' }}>
                    <button
                      className="btn btn-secondary btn-sm"
                      onClick={() => handleReroute(j)}
                    >
                      Reroute
                    </button>
                    <button
                      className="btn btn-secondary btn-sm"
                      onClick={() => handleSplit(j)}
                    >
                      Split Leg
                    </button>
                    <button
                      className="btn btn-danger btn-sm"
                      onClick={() => handleCancel(j)}
                    >
                      Cancel
                    </button>
                    <label style={{ display: 'flex', alignItems: 'center', gap: '4px', fontSize: '0.75rem', marginLeft: 'auto' }}>
                      <input
                        type="checkbox"
                        checked={selectedJourneysForMerge.includes(j.id)}
                        onChange={(e) => {
                          if (e.target.checked) {
                            setSelectedJourneysForMerge([...selectedJourneysForMerge, j.id]);
                          } else {
                            setSelectedJourneysForMerge(selectedJourneysForMerge.filter((id) => id !== j.id));
                          }
                        }}
                      />
                      Select to Merge
                    </label>
                  </div>
                </div>
              ))}

              {selectedJourneysForMerge.length >= 2 && (
                <div style={{ backgroundColor: 'var(--primary-light)', padding: '0.75rem', borderRadius: '0.375rem', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                  <span style={{ fontSize: '0.875rem' }}>
                    {selectedJourneysForMerge.length} journeys selected for consolidation batch
                  </span>
                  <button className="btn btn-primary btn-sm" onClick={handleMerge}>
                    Merge Selected
                  </button>
                </div>
              )}
            </div>
          )}
        </div>

        {/* Report Disruption */}
        <div className="card">
          <div className="card-header">
            <h3 className="card-title">Network Disruption & Replanning</h3>
          </div>

          <form onSubmit={handleReportDisruption}>
            <p style={{ fontSize: '0.875rem', color: 'var(--gray-600)', marginBottom: '1rem' }}>
              Report when a worker, node, connection or laboratory becomes unavailable. The system will replan unfinished work while preserving completed stops and custody.
            </p>

            <div className="form-group">
              <label className="form-label">Disruption Target Type</label>
              <select
                className="form-select"
                value={disruptionTargetType}
                onChange={(e) => {
                  const t = e.target.value as any;
                  setDisruptionTargetType(t);
                  setDisruptionTargetId('');
                }}
              >
                <option value="worker">Worker</option>
                <option value="node">Collection Node / Hub</option>
                <option value="laboratory">Laboratory</option>
                <option value="connection">Transport Connection</option>
              </select>
            </div>

            <div className="form-group">
              <label className="form-label">Select Unavailable Entity</label>
              <select
                className="form-select"
                value={disruptionTargetId}
                onChange={(e) => setDisruptionTargetId(e.target.value)}
                required
              >
                <option value="">-- Choose Unavailable Item --</option>
                {disruptionTargetType === 'worker' &&
                  opWorkers.map((w) => (
                    <option key={w.id} value={w.id}>
                      {w.fullName || w.username} ({w.activeRole || 'Worker'})
                    </option>
                  ))}
                {disruptionTargetType === 'node' &&
                  locations
                    .filter((l) => l.isCollectionPoint || l.isHub)
                    .map((l) => (
                      <option key={l.id} value={l.id}>
                        {l.name} ({l.code})
                      </option>
                    ))}
                {disruptionTargetType === 'laboratory' &&
                  locations
                    .filter((l) => l.isLaboratory)
                    .map((l) => (
                      <option key={l.id} value={l.id}>
                        Lab: {l.name} ({l.code})
                      </option>
                    ))}
                {disruptionTargetType === 'connection' &&
                  connections.map((c) => (
                    <option key={c.id} value={c.id}>
                      Connection: {c.fromLocationId} → {c.toLocationId}
                    </option>
                  ))}
              </select>
            </div>

            <div className="form-group">
              <label className="form-label">Reason / Notes</label>
              <textarea
                className="form-textarea"
                rows={2}
                value={disruptionReason}
                onChange={(e) => setDisruptionReason(e.target.value)}
                required
              />
            </div>

            <button type="submit" className="btn btn-danger" aria-label="Trigger Disruption Replanning">
              Trigger Disruption Replanning
            </button>
          </form>
        </div>
      </div>

      {selectedSampleId && (
        <SampleDetailModal
          sampleId={selectedSampleId}
          workers={opWorkers}
          locations={locations}
          onClose={() => {
            setSelectedSampleId(null);
            loadOperations();
          }}
        />
      )}
    </div>
  );
};
"}

{"summary":"Create AuditTrailView component","command":"create","path":"/workspace/frontend/src/components/AuditTrailView.tsx","file_text":"import React, { useState, useEffect } from 'react';
import { api, ApiError } from '../api/client';
import { AuditEvent, User } from '../types';

interface AuditTrailViewProps {
  workers: User[];
}

export const AuditTrailView: React.FC<AuditTrailViewProps> = ({ workers }) => {
  const [events, setEvents] = useState<AuditEvent[]>([]);
  const [sampleId, setSampleId] = useState('');
  const [userId, setUserId] = useState('');
  const [action, setAction] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const searchLogs = async () => {
    setIsLoading(true);
    setError(null);
    try {
      const res = await api.searchAuditTrail({
        sampleId: sampleId || undefined,
        userId: userId || undefined,
        action: action || undefined,
        limit: 100,
      });
      setEvents(res.auditTrail || []);
    } catch (err: any) {
      if (err instanceof ApiError) {
        setError(err.message || 'Failed to query audit trail');
      } else {
        setError(err.message || 'Network error');
      }
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    searchLogs();
  }, []);

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    searchLogs();
  };

  return (
    <div className="card">
      <div className="card-header">
        <h2 className="card-title">System Audit Trail & Compliance Log</h2>
        <span className="badge badge-info">Searchable Audit Events</span>
      </div>

      <form onSubmit={handleSearch} style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '1rem', marginBottom: '1.5rem' }}>
        <div className="form-group" style={{ marginBottom: 0 }}>
          <label className="form-label" htmlFor="audit-sample">Sample ID / Tracking</label>
          <input
            id="audit-sample"
            type="text"
            className="form-input"
            placeholder="Search by Sample ID..."
            value={sampleId}
            onChange={(e) => setSampleId(e.target.value)}
          />
        </div>

        <div className="form-group" style={{ marginBottom: 0 }}>
          <label className="form-label" htmlFor="audit-user">User</label>
          <select
            id="audit-user"
            className="form-select"
            value={userId}
            onChange={(e) => setUserId(e.target.value)}
          >
            <option value="">-- All Users --</option>
            {workers.map((w) => (
              <option key={w.id} value={w.id}>
                {w.fullName || w.username} ({w.activeRole || 'User'})
              </option>
            ))}
          </select>
        </div>

        <div className="form-group" style={{ marginBottom: 0 }}>
          <label className="form-label" htmlFor="audit-action">Action Filter</label>
          <input
            id="audit-action"
            type="text"
            className="form-input"
            placeholder="e.g. handoff, seal, login..."
            value={action}
            onChange={(e) => setAction(e.target.value)}
          />
        </div>

        <div style={{ display: 'flex', alignItems: 'flex-end' }}>
          <button type="submit" className="btn btn-primary" style={{ width: '100%' }} disabled={isLoading}>
            {isLoading ? 'Searching...' : 'Search Logs'}
          </button>
        </div>
      </form>

      {error && (
        <div style={{ padding: '0.75rem', backgroundColor: 'var(--danger-light)', color: 'var(--danger)', borderRadius: '0.375rem', marginBottom: '1rem' }}>
          {error}
        </div>
      )}

      <div className="table-container">
        <table className="table">
          <thead>
            <tr>
              <th>Timestamp</th>
              <th>User & Role</th>
              <th>Action</th>
              <th>Item / Resource</th>
              <th>Outcome</th>
              <th>Details & Changes</th>
            </tr>
          </thead>
          <tbody>
            {events.length === 0 ? (
              <tr>
                <td colSpan={6} style={{ textAlign: 'center', padding: '1.5rem', color: 'var(--gray-500)' }}>
                  No audit logs found matching criteria.
                </td>
              </tr>
            ) : (
              events.map((ev) => (
                <tr key={ev.id}>
                  <td style={{ fontSize: '0.75rem', color: 'var(--gray-500)', whiteSpace: 'nowrap' }}>
                    {new Date(ev.timestamp).toLocaleString()}
                  </td>
                  <td>
                    <div style={{ fontWeight: 600 }}>{ev.username || ev.userId || 'System'}</div>
                    <div style={{ fontSize: '0.75rem', color: 'var(--gray-500)' }}>{ev.role || 'system'}</div>
                  </td>
                  <td>
                    <span className="badge badge-gray">{ev.action}</span>
                  </td>
                  <td>
                    <div style={{ fontSize: '0.8125rem' }}>{ev.itemType}</div>
                    <div style={{ fontSize: '0.75rem', color: 'var(--gray-500)' }}>{ev.itemId || '-'}</div>
                  </td>
                  <td>
                    <span
                      className={`badge ${
                        ev.outcome === 'success'
                          ? 'badge-success'
                          : ev.outcome === 'exception'
                          ? 'badge-warning'
                          : 'badge-danger'
                      }`}
                    >
                      {ev.outcome}
                    </span>
                  </td>
                  <td>
                    <pre
                      style={{
                        margin: 0,
                        fontSize: '0.75rem',
                        fontFamily: 'monospace',
                        maxHeight: '80px',
                        overflowY: 'auto',
                        whiteSpace: 'pre-wrap',
                        color: 'var(--gray-700)',
                      }}
                    >
                      {ev.details ? JSON.stringify(ev.details, null, 1) : '-'}
                    </pre>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};
"}

{"file_text":"import React, { useState } from 'react';
import { api, ApiError } from '../api/client';
import { User, Location, NetworkConnection, SampleType, UserRole } from '../types';

interface AdminPanelProps {
  users: User[];
  locations: Location[];
  connections: NetworkConnection[];
  sampleTypes: SampleType[];
  onRefreshAll: () => void;
}

export const AdminPanel: React.FC<AdminPanelProps> = ({
  users,
  locations,
  connections,
  sampleTypes,
  onRefreshAll,
}) => {
  const [activeAdminTab, setActiveAdminTab] = useState<'users' | 'locations' | 'connections' | 'sampleTypes'>('users');
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);

  // User form
  const [newUsername, setNewUsername] = useState('');
  const [newPassword, setNewPassword] = useState('Password123!');
  const [newFullName, setNewFullName] = useState('');
  const [newUserRoles, setNewUserRoles] = useState<UserRole[]>(['certified_collection_professional']);
  const [newQualifications, setNewQualifications] = useState<string>('Amber,Indigo,Frost,Pulse');
  const [newAssignedLocationId, setNewAssignedLocationId] = useState<string>('');

  // Location form
  const [locName, setLocName] = useState('');
  const [locCode, setLocCode] = useState('');
  const [locLat, setLocLat] = useState(12.9716);
  const [locLng, setLocLng] = useState(77.5946);
  const [locIsCollection, setLocIsCollection] = useState(true);
  const [locIsTransfer, setLocIsTransfer] = useState(false);
  const [locIsHub, setLocIsHub] = useState(false);
  const [locIsLab, setLocIsLab] = useState(false);
  const [locRegCap, setLocRegCap] = useState(100);
  const [locCoolCap, setLocCoolCap] = useState(50);
  const [locHandlingMins, setLocHandlingMins] = useState(10);
  const [locAcceptedSamples, setLocAcceptedSamples] = useState('Amber,Indigo,Frost,Pulse');

  // Connection form
  const [connFrom, setConnFrom] = useState(locations[0]?.id || '');
  const [connTo, setConnTo] = useState(locations[1]?.id || '');
  const [connDist, setConnDist] = useState(10);
  const [connTime, setConnTime] = useState(25);
  const [connRegCap, setConnRegCap] = useState(50);
  const [connCoolCap, setConnCoolCap] = useState(20);

  // Sample type form
  const [stCode, setStCode] = useState('');
  const [stName, setStName] = useState('');
  const [stContainer, setStContainer] = useState('Standard Tube Box');
  const [stMinTemp, setStMinTemp] = useState(2);
  const [stMaxTemp, setStMaxTemp] = useState(8);
  const [stRequiresCooled, setStRequiresCooled] = useState(false);
  const [stRequiresQualified, setStRequiresQualified] = useState(true);
  const [stIncompatibilities, setStIncompatibilities] = useState('');
  const [stIsTimeCritical, setStIsTimeCritical] = useState(false);
  const [stMaxTransitTime, setStMaxTransitTime] = useState(240);

  const clearMessages = () => {
    setError(null);
    setSuccess(null);
  };

  const handleCreateUser = async (e: React.FormEvent) => {
    e.preventDefault();
    clearMessages();
    try {
      await api.createUser({
        username: newUsername,
        password: newPassword,
        fullName: newFullName,
        roles: newUserRoles,
        qualifications: newQualifications.split(',').map((s) => s.trim()).filter(Boolean),
        assignedLocationId: newAssignedLocationId || undefined,
      });
      setSuccess(`User ${newUsername} created successfully`);
      setNewUsername('');
      setNewFullName('');
      onRefreshAll();
    } catch (err: any) {
      setError(err.message || 'Failed to create user');
    }
  };

  const handleToggleUserActive = async (user: User) => {
    clearMessages();
    try {
      await api.updateUserAccess({
        userId: user.id,
        active: !user.active,
      });
      setSuccess(`User ${user.username} ${user.active ? 'deactivated' : 'activated'}`);
      onRefreshAll();
    } catch (err: any) {
      setError(err.message || 'Failed to update user status');
    }
  };

  const handleCreateLocation = async (e: React.FormEvent) => {
    e.preventDefault();
    clearMessages();
    try {
      await api.createLocation({
        name: locName,
        code: locCode,
        latitude: locLat,
        longitude: locLng,
        isCollectionPoint: locIsCollection,
        isTransferPoint: locIsTransfer,
        isHub: locIsHub,
        isLaboratory: locIsLab,
        regularCapacity: locRegCap,
        cooledCapacity: locCoolCap,
        handlingTimeMinutes: locHandlingMins,
        acceptedSampleTypes: locAcceptedSamples.split(',').map((s) => s.trim()).filter(Boolean),
      });
      setSuccess(`Location ${locName} created successfully`);
      setLocName('');
      setLocCode('');
      onRefreshAll();
    } catch (err: any) {
      setError(err.message || 'Failed to create location');
    }
  };

  const handleToggleLocationActive = async (loc: Location) => {
    clearMessages();
    try {
      await api.setLocationStatus(loc.id, !loc.active);
      setSuccess(`Location ${loc.name} ${loc.active ? 'deactivated' : 'activated'}`);
      onRefreshAll();
    } catch (err: any) {
      setError(err.message || 'Failed to toggle location status');
    }
  };

  const handleToggleFunctionActive = async (loc: Location, fnType: 'collection' | 'transfer' | 'hub' | 'laboratory', currentVal: boolean) => {
    clearMessages();
    try {
      await api.setLocationFunctionStatus({
        locationId: loc.id,
        functionType: fnType,
        active: !currentVal,
      });
      setSuccess(`Function ${fnType} on ${loc.name} updated`);
      onRefreshAll();
    } catch (err: any) {
      setError(err.message || 'Failed to update function status');
    }
  };

  const handleCreateConnection = async (e: React.FormEvent) => {
    e.preventDefault();
    clearMessages();
    try {
      await api.createConnection({
        fromLocationId: connFrom,
        toLocationId: connTo,
        distanceKm: Number(connDist),
        transitTimeMinutes: Number(connTime),
        regularCapacity: Number(connRegCap),
        cooledCapacity: Number(connCoolCap),
      });
      setSuccess('Connection created successfully');
      onRefreshAll();
    } catch (err: any) {
      setError(err.message || 'Failed to create connection');
    }
  };

  const handleToggleConnection = async (conn: NetworkConnection) => {
    clearMessages();
    try {
      await api.setConnectionStatus(conn.id, !conn.active);
      setSuccess(`Connection ${conn.active ? 'deactivated' : 'activated'}`);
      onRefreshAll();
    } catch (err: any) {
      setError(err.message || 'Failed to toggle connection');
    }
  };

  const handleCreateSampleType = async (e: React.FormEvent) => {
    e.preventDefault();
    clearMessages();
    try {
      await api.createSampleType({
        code: stCode,
        name: stName,
        container: stContainer,
        minTempC: Number(stMinTemp),
        maxTempC: Number(stMaxTemp),
        requiresCooled: stRequiresCooled,
        requiresQualifiedCollector: stRequiresQualified,
        incompatibleSampleTypes: stIncompatibilities.split(',').map((s) => s.trim()).filter(Boolean),
        isTimeCritical: stIsTimeCritical,
        maxTransitTimeMinutes: Number(stMaxTransitTime),
      });
      setSuccess(`Sample type ${stName} created successfully`);
      setStCode('');
      setStName('');
      onRefreshAll();
    } catch (err: any) {
      setError(err.message || 'Failed to create sample type');
    }
  };

  return (
    <div>
      <div style={{ marginBottom: '1.25rem' }}>
        <h2 style={{ fontSize: '1.5rem', fontWeight: 700, color: 'var(--gray-900)' }}>
          Administration Panel
        </h2>
        <p style={{ fontSize: '0.875rem', color: 'var(--gray-500)' }}>
          Manage network nodes, laboratories, users, certifications, sample types, and network connections
        </p>
      </div>

      {error && (
        <div style={{ padding: '0.75rem', backgroundColor: 'var(--danger-light)', color: 'var(--danger)', borderRadius: '0.375rem', marginBottom: '1rem' }}>
          ❌ {error}
        </div>
      )}

      {success && (
        <div style={{ padding: '0.75rem', backgroundColor: 'var(--success-light)', color: 'var(--success)', borderRadius: '0.375rem', marginBottom: '1rem' }}>
          ✓ {success}
        </div>
      )}

      {/* Admin Tabs */}
      <div className="card">
        <div className="tabs">
          <button
            className={`tab ${activeAdminTab === 'users' ? 'active' : ''}`}
            onClick={() => setActiveAdminTab('users')}
          >
            Users & Certifications ({users.length})
          </button>
          <button
            className={`tab ${activeAdminTab === 'locations' ? 'active' : ''}`}
            onClick={() => setActiveAdminTab('locations')}
          >
            Locations & Laboratories ({locations.length})
          </button>
          <button
            className={`tab ${activeAdminTab === 'connections' ? 'active' : ''}`}
            onClick={() => setActiveAdminTab('connections')}
          >
            Network Connections ({connections.length})
          </button>
          <button
            className={`tab ${activeAdminTab === 'sampleTypes' ? 'active' : ''}`}
            onClick={() => setActiveAdminTab('sampleTypes')}
          >
            Sample Types ({sampleTypes.length})
          </button>
        </div>

        {/* USERS TAB */}
        {activeAdminTab === 'users' && (
          <div className="grid grid-cols-2">
            <div>
              <h3 style={{ fontSize: '1.125rem', fontWeight: 600, marginBottom: '1rem' }}>Add New User</h3>
              <form onSubmit={handleCreateUser}>
                <div className="form-group">
                  <label className="form-label">Username</label>
                  <input
                    type="text"
                    className="form-input"
                    value={newUsername}
                    onChange={(e) => setNewUsername(e.target.value)}
                    required
                  />
                </div>

                <div className="form-group">
                  <label className="form-label">Password</label>
                  <input
                    type="password"
                    className="form-input"
                    value={newPassword}
                    onChange={(e) => setNewPassword(e.target.value)}
                    required
                  />
                </div>

                <div className="form-group">
                  <label className="form-label">Full Name</label>
                  <input
                    type="text"
                    className="form-input"
                    value={newFullName}
                    onChange={(e) => setNewFullName(e.target.value)}
                  />
                </div>

                <div className="form-group">
                  <label className="form-label">Roles (select multiple)</label>
                  <select
                    multiple
                    className="form-select"
                    style={{ height: '120px' }}
                    value={newUserRoles}
                    onChange={(e) => {
                      const selected = Array.from(e.target.selectedOptions, (option) => option.value as UserRole);
                      setNewUserRoles(selected);
                    }}
                  >
                    <option value="requester">Requester</option>
                    <option value="certified_collection_professional">Certified Collection Professional</option>
                    <option value="relay_courier">Relay Courier</option>
                    <option value="node_handler">Node Handler</option>
                    <option value="laboratory_intake_operator">Laboratory Intake Operator</option>
                    <option value="dispatcher">Dispatcher</option>
                    <option value="administrator">Administrator</option>
                  </select>
                </div>

                <div className="form-group">
                  <label className="form-label">Qualifications / Certifications (comma separated)</label>
                  <input
                    type="text"
                    className="form-input"
                    value={newQualifications}
                    onChange={(e) => setNewQualifications(e.target.value)}
                    placeholder="Amber, Indigo, Frost, Pulse"
                  />
                </div>

                <div className="form-group">
                  <label className="form-label">Assigned Location (Node Handler / Lab Operator)</label>
                  <select
                    className="form-select"
                    value={newAssignedLocationId}
                    onChange={(e) => setNewAssignedLocationId(e.target.value)}
                  >
                    <option value="">-- No specific assigned facility --</option>
                    {locations.map((loc) => (
